const STATUS={draft:"Чернетка",submitted:"Подано",revision:"Доопрацювати",resubmitted:"Виправлено, на повторній перевірці",approved:"Погоджено",working:"Робочий етап",collected:"Первинний збір сформовано"};
const JUSTIFICATION_SECTION={"id":"choice-justification","title":"1.1. Обґрунтування вибору","intro":"**Обґрунтування вибору** допомагає режисерові зрозуміти, чому саме цей проєкт має бути створений, чому він важливий зараз і чи реально втілити його у конкретних умовах. Це не формальна відповідь на питання «чому мені цікава тема», а послідовне осмислення історичного, соціального, мистецького, авторського та практичного контексту майбутньої постановки.\n\n**Методична підказка.** Теоретичний матеріал можна відкривати за потреби. Він допомагає сформулювати власне рішення, а не підставити готову відповідь.","published":true,"blocks":[{"id":"choiceHistorical","type":"textarea","title":"1.1.1. Історичний аспект","help":"Визначте історичний, культурний або біографічний контекст теми. Проведіть ґрунтовне дослідження історії теми, її розвитку та контексту, зазначте використані джерела.","placeholder":"Дослідіть історію обраної теми, основні етапи розвитку, події, постаті та джерела...","theory":"**Історичний аспект** - це ґрунтовне дослідження історії теми, яку ви обрали для свого майбутнього сценічного проєкту. Перш ніж створювати концерт, шоу чи виставу, режисер повинен добре розібратися в матеріалі.\n\nДослідіть, як виникла обрана тема, які події та люди вплинули на її розвиток, як змінювалося її значення з часом. Важливо не лише зібрати факти, а й зрозуміти, чому відбувалися певні зміни та як вони пов'язані між собою.\n\n**Якщо проєкт присвячений артисту**, вивчіть не тільки його біографію і пісні, а й культурне середовище, у якому він працював, творчий шлях, вплив інших митців і значення його творчості. **Якщо тема стосується мистецького явища**, простежте його історію від виникнення до сучасності. **Якщо в основі історична подія**, дослідіть її передумови, перебіг, учасників та наслідки.\n\nВикористовуйте книги, наукові публікації, архівні матеріали, інтерв'ю, документальні фільми, фотографії, аудіо- та відеозаписи. Порівнюйте джерела, перевіряйте факти й **обов'язково зазначайте, звідки взято інформацію**.\n\n**Історичне дослідження повинно бути ґрунтовним.** Це не коротка довідка й не формальний вступ. Його мета - допомогти вам глибоко зрозуміти матеріал, із яким працюватимете як режисер."},{"id":"choiceSocial","type":"textarea","title":"1.1.2. Соціальний аспект","help":"Поясніть, чому ця тема важлива сучасній людині та для кого вона є актуальною.","placeholder":"У чому сучасна актуальність теми, кого вона стосується, які питання порушує...","theory":"**Соціальний аспект** показує, як тема пов'язана із сучасною людиною, суспільством, культурою та конкретною аудиторією. Навіть розважальний концерт, шоу чи церемонія існують у певному соціальному середовищі й відображають його цінності, настрої, суперечності та очікування.\n\nВизначте, яка сучасна проблема, потреба або явище стоїть за вашою темою, кого це стосується, чому про це варто говорити саме зараз, які думки або почуття тема може викликати в глядача.\n\n**Недостатньо написати «тема актуальна».** Поясніть, у чому саме полягає її актуальність і для кого вона є актуальною.\\n\\n**Приклад для сценічного проєкту.** Молодіжне музичне шоу про самовираження може бути актуальним для аудиторії, яка відчуває тиск очікувань. Важливо назвати не просто «молодь», а конкретну потребу: бути почутим і прийнятим.\\n\\n**Що саме вписувати.** Назвіть аудиторію, актуальну для неї суперечність і причину, чому сценічна подія здатна викликати розмову про неї. Не пишіть лише «тема важлива сьогодні»."},{"id":"choiceArtistic","type":"textarea","title":"1.1.3. Мистецький аспект","help":"Поясніть, чому цю тему варто втілювати саме як сценічний мистецько-видовищний проєкт.","placeholder":"Що саме сценічна форма дає цій темі: музика, простір, світло, пластика, відео, жива присутність...","theory":"**Мистецький аспект** - це дослідження того, як обрана тема вже була представлена в мистецтві, які твори, концерти, вистави, шоу чи інші проєкти були їй присвячені та які творчі рішення використовували митці.\n\nОзнайомтеся з постановками на близьку тему не лише у вашому жанрі, а й в інших видах мистецтва. Наприклад, тему життя композитора могли розкривати в концертних програмах, музичних виставах, документальному кіно та телевізійних проєктах. Важливо побачити, наскільки по-різному можна працювати з одним матеріалом.\n\nПід час перегляду звертайте увагу на сценічну дію, образи, структуру, використання музики, хореографії, сценографії, світла, відео та взаємодію з глядачем. Порівнюйте різні підходи та пояснюйте, як конкретні рішення впливають на сприйняття твору. Не обмежуйтеся словами «сподобалося» або «не сподобалося».\n\nДосліджуйте мистецькі традиції, розвиток сценічних форм і сучасні творчі пошуки. Використовуйте повні записи постановок, інтерв'ю режисерів, рецензії, програми, афіші та професійні публікації. **Зазначайте назви, авторів, роки створення й посилання на джерела.**\n\n**Мета мистецького аспекту** - зрозуміти, що вже створено на обрану тему, чого можна навчитися з досвіду інших митців і як уникнути несвідомого повторення чужих рішень. Власний режисерський задум розроблятимете пізніше."},{"id":"choiceAuthor","type":"textarea","title":"1.1.4. Авторський аспект","help":"Сформулюйте, чому саме ви як режисер хочете говорити про цю тему.","placeholder":"Що вас особисто зачепило, хвилює, надихає або змушує поставити це питання...","theory":"**Авторський аспект** виявляє вашу особисту режисерську мотивацію. Чому саме ви хочете говорити про цю тему? Що в ній вас зачепило, здивувало, обурило, надихнуло або змусило замислитися?\n\nДжерелом може бути особистий досвід, життєве спостереження, професійний інтерес, певна подія, емоційний зв'язок із темою, бажання висловити позицію або спробувати нову сценічну форму.\n\n**Авторський аспект не зобов'язує до надмірної особистої відвертості.** Йдеться насамперед про власну художню позицію та місце цієї теми у вашому режисерському мисленні.\\n\\n**Приклад для сценічного проєкту.** Режисер обирає концерт про спадкоємність не лише тому, що любить музику певного артиста, а тому, що хоче показати, як його пісні звучать у досвіді нового покоління.\\n\\n**Що саме вписувати.** Напишіть від першої особи: що саме вас хвилює, яку позицію ви прагнете висловити і чому обрали саме цей сценічний матеріал. Уникайте загального «мені подобається ця тема»."},{"id":"choiceFactorsReality","type":"textarea","title":"1.1.5. Чинники вибору та реальності проєкту","help":"Поєднайте об'єктивні та суб'єктивні чинники з реальною можливістю здійснити проєкт у ваших умовах.","placeholder":"Що об'єктивно і суб'єктивно впливає на вибір проєкту? Які ресурси є? Чого бракує? Що потрібно адаптувати або переосмислити?","wide":true,"theory":"На вибір і можливість реалізації проєкту одночасно впливають **об'єктивні, суб'єктивні та практичні чинники**. Їх доцільно розглядати разом, оскільки режисер працює не в абстрактних умовах, а співвідносить власний задум із конкретною реальністю.\n\n**Об'єктивні чинники** - це обставини, що існують незалежно від ваших особистих симпатій: сучасність і актуальність проблеми, конкретна подія або замовлення, аудиторія, майданчик, бюджет, склад команди, технічна база, терміни, логістика та безпекові умови.\n\n**Суб'єктивні чинники** пов'язані з вами як режисером: світогляд, особиста мотивація, професійний досвід, творчі здібності, образне мислення, естетичні впливи та попередній мистецький досвід.\n\nДалі потрібно провести **перевірку задуму на реальність**. Оцініть, що у вашому розпорядженні вже є, що реально можна отримати, а що поки існує лише у бажаній моделі проєкту. Якщо задум вимагає ресурсів, яких немає, визначте, що можна змінити, скоротити, замінити або переосмислити без втрати головного сенсу.\n\n**Розрізняйте художньо бажане і реально можливе.** Обмеження не завжди послаблюють проєкт. Часто вони змушують знайти точніше, образніше й винахідливіше рішення.\n\n**Головне питання:** чи можу я реально поставити цей проєкт у тих умовах, у яких працюю?\\n\\n**Приклад для сценічного проєкту.** Замість великої рухомої декорації за обмеженого бюджету можна використати світлове зонування і пластичну трансформацію простору. Художня мета залишається, засіб змінюється.\\n\\n**Що саме вписувати.** Розділіть наявні ресурси, ризики та рішення щодо адаптації. Назвіть реальний майданчик, кількість виконавців, часові й технічні обмеження."},{"id":"choiceSummary","type":"textarea","title":"1.1.6. Підсумкове обґрунтування вибору проєкту","help":"На основі попередніх відповідей сформулюйте один цілісний авторський текст. Це підсумок усього підрозділу 1.1.","placeholder":"Сформулюйте повне обґрунтування вибору проєкту одним зв'язним текстом...","wide":true,"summary":true,"theory":"**Підсумкове обґрунтування** - це не ще одна коротка відповідь, а завершений зв'язний текст, який об'єднує всі попередні аспекти в цілісну картину.\n\nУ тексті мають природно поєднатися історичний і соціальний контекст, мистецький потенціал теми, ваша авторська мотивація, чинники вибору та реальна можливість здійснення проєкту.\n\n**Не копіюйте механічно попередні відповіді.** Перебудуйте їх у логічний авторський текст, у якому одна думка переходить в іншу.\n\nПісля завершення цього пункту читач повинен зрозуміти: **чому саме цей проєкт, чому саме зараз, чому він важливий для глядача, чому саме ви хочете його створити і чи реально його втілити.**\\n\\n**Приклад для сценічного проєкту.** «Обираю концерт, присвячений спадкоємності музичної традиції, оскільки пісні попередніх поколінь продовжують формувати сучасних виконавців. Жива сцена дозволяє показати цю взаємодію через спільне виконання, а доступний склад артистів робить задум здійсненним».\\n\\n**Що саме вписувати.** Напишіть 2-4 зв’язні абзаци, а не шість механічно скопійованих відповідей. Читач має зрозуміти цінність, авторську позицію і реалістичність."}]};
const PROJECT_PARAMETERS_SECTION={"id":"project-parameters","title":"1.2. Вихідні параметри проєкту","intro":"Цей розділ фіксує вихідні характеристики майбутнього проєкту. Тут важливо коротко і точно визначити, що саме ви створюєте, для кого, де, коли, у якому масштабі та просторі. Теоретичне пояснення до кожного пункту відкривається окремо.\n\n**Методична підказка.** Теоретичний матеріал можна відкривати за потреби. Він допомагає сформулювати власне рішення, а не підставити готову відповідь.","published":true,"blocks":[{"id":"projectTitle","type":"text","title":"1.2.1. Назва проєкту","help":"Назва може бути робочою. Вона має відображати ідею, смисловий напрям або центральний образ проєкту.","placeholder":"Введіть назву проєкту","required":true,"theory":"Назва проєкту - це концентроване словесне вираження його ідеї та змісту. Вона не просто позначає подію, а має спрямовувати сприйняття глядача до головного смислу, авторського задуму або центрального образу.\n\nНа початковому етапі назва може бути робочою. У процесі роботи над проблемою, темою, ідеєю, художнім образом і режисерським задумом вона може уточнюватися або повністю змінюватися.\n\nНазва може бути прямою, образною, метафоричною, символічною або асоціативною. Головне, щоб вона відповідала ідеї проєкту, не була випадковою і могла органічно існувати в афіші, програмі та комунікації з глядачем.\n\nПеревірте себе питанням: чи передає ця назва головний смисловий напрям мого проєкту?\\n\\n**Приклад для сценічного проєкту.** «Голоси крізь час» може бути назвою концерту про спадкоємність, якщо ця метафора справді реалізується в програмі, а не існує тільки на афіші.\\n\\n**Що саме вписувати.** Запропонуйте назву, поясніть її зв’язок з ідеєю і перевірте, чи зрозуміла вона глядачеві. Уникайте порожніх пафосних формул."},{"id":"projectForm","type":"text","title":"1.2.2. Форма проєкту","help":"Вкажіть форму без прикметників: концерт, шоу, вистава, вечір, церемонія, конкурс, фестиваль, свято або презентація.","placeholder":"Наприклад: концерт","theory":"Форма проєкту - це тип сценічної або мистецько-видовищної організації майбутньої події. Вона відповідає на базове питання: що саме я створюю?\n\nУ назві форми не використовуйте прикметники, які характеризують художню природу проєкту. Такі уточнення з’являться у жанрі. Наприклад, форма: концерт. Жанрове уточнення: тематичний, ювілейний, гумористичний тощо.\n\nКОНЦЕРТ\nПублічний виступ артистів за визначеною, заздалегідь складеною програмою. Основна особливість концерту - побудова з окремих номерів, кожен із яких має відносну самостійність. Номери поєднуються режисером у цілісну програму.\n\nШОУ\nВидовищна сценічна форма, в основі якої лежать яскраві номери, атракціони та виразне використання технічних можливостей. Для шоу характерні видовищність, динаміка, візуальна виразність і сильний емоційний вплив. Чіткий сюжетний хід не є обов’язковим.\n\nШОУ-ВИСТАВА / ВИСТАВА\nСценічна форма, побудована за законами єдиної дії, історії або сюжету. У шоу-виставі поєднуються принципи театральної вистави та видовищного шоу. Номери, технічні компоненти, сценографія та інші засоби підпорядковуються єдиній дії. Основна відмінність від концерту - обов’язкова сюжетна або чітко розгорнута драматургічна побудова.\n\nВЕЧІР\nОсоблива сценічна форма, у якій поєднуються художні та документальні матеріали. Для вечора характерні реальні герої, документи, спогади, архівні матеріали та жива комунікація з аудиторією. Зазвичай вечір має конкретну присвяту людині, події, даті або мистецькому явищу.\n\nЦЕРЕМОНІЯ\nУрочисте видовищне дійство з ритуально-обрядовою природою. Воно створюється з особливої нагоди: відкриття, закриття, нагородження, вшанування, посвяти тощо. Основна особливість - чіткий порядок символічних і ритуальних дій, які режисер перетворює на художньо осмислену сценічну подію.\n\nКОНКУРС\nПублічне змагання, у якому через виступи, демонстрацію майстерності або творчих досягнень визначають найкращих серед учасників. Обов’язковими є змагальність, правила, критерії оцінювання та результат. Саме невідомість результату створює природну драматургію напруження.\n\nФЕСТИВАЛЬ\nМасове мистецьке або культурне дійство, що об’єднує численних учасників, жанри, події, сцени та аудиторії. Основні риси фестивалю - масштабність і поліжанровість. Окремі події поєднуються спільною темою, ідеєю, образом і загальною режисерською логікою.\n\nСВЯТО\nМасове культурне дійство, приурочене до певної події, дати або теми, яке об’єднує людей спільним переживанням. У межах свята можуть поєднуватися концерти, сценічні виступи, ігрові зони, виставкові та інтерактивні складові. Режисер має об’єднати різні компоненти в одну масштабну подію.\n\nПРЕЗЕНТАЦІЯ\nТеатралізоване публічне дійство, спрямоване на представлення нового продукту, ідеї, твору або проєкту. Основна особливість - наявність конкретного об’єкта презентації, навколо якого будується вся драматургія. Режисер організовує не лише показ, а й момент відкриття, інтригу, емоційне сприйняття та запам’ятовування представленого об’єкта.\n\n**Наведений перелік не є вичерпним.** Можливо, ваш задум точніше відповідає іншій сценічній або мистецько-видовищній формі. Ви можете запропонувати власний варіант, якщо здатні пояснити, чому саме ця форма відповідає природі проєкту, його змісту та способу взаємодії з глядачем.\n\nПід час вибору форми не намагайтеся зробити назву складнішою. Спочатку точно визначте, до якого типу великої сценічної події належить ваш задум. Художні уточнення ви сформулюєте в пункті «Жанр».\\n\\n**Приклад для сценічного проєкту.** «Концерт» описує організацію з відносно самостійних номерів. «Церемонія» передбачає ритуальну послідовність дій. «Шоу-вистава» має наскрізну дію або сюжетну логіку.\\n\\n**Що саме вписувати.** Вкажіть основну форму одним точним терміном. Не підміняйте форму жанром: «ліричний», «святковий» або «молодіжний» характеризують твір, але не визначають його організацію."},{"id":"projectGenre","type":"text","title":"1.2.3. Жанр","help":"Уточніть художню природу обраної форми. Саме тут з’являються характеристики, які не слід додавати до назви форми.","placeholder":"Вкажіть жанрову характеристику","theory":"Жанр - це авторське бачення та мистецька конкретизація форми проєкту. Якщо форма відповідає на питання «що саме я створюю?», то жанр уточнює, яким є цей проєкт художньо, в якому емоційному, стильовому та образному ключі він існує.\n\nСаме в жанрі з’являються прикметникові характеристики. Наприклад, форма може бути «концерт», а жанрове визначення уточнює його художню природу: тематичний, ювілейний, гумористичний та інший відповідно до конкретного задуму.\n\nЖанр впливає на характер сценічної дії, спосіб існування виконавців, режисерські прийоми, музику, світло, сценографію, пластичне рішення, монтаж і темпоритм. Усі складові постановки мають існувати в єдиному жанровому ключі.\n\nНе обирайте жанр тільки як красиве слово. Він повинен реально проявлятися у способі, яким ви будете будувати проєкт.\\n\\n**Приклад для сценічного проєкту.** Для форми «концерт» можна визначити жанрову природу як «концерт-спогад» або «театралізований концерт», якщо це підтверджено реальною побудовою.\\n\\n**Що саме вписувати.** Поясніть, яка емоційна, стилістична чи драматургічна особливість визначає жанр. Не дублюйте слово з графи «форма»."},{"id":"projectScale","type":"text","title":"1.2.4. Масштаб проєкту","help":"Визначте масштаб події та рівень її охоплення. За потреби вкажіть орієнтовну кількість учасників і глядачів.","placeholder":"Наприклад: великий, міський","theory":"Масштаб визначає розмір, складність і рівень охоплення майбутнього проєкту. Його доцільно розглядати у двох площинах.\n\nЗа масштабом самої події: камерний, середній, великий, масовий.\n\nЗа рівнем охоплення: локальний, міський, регіональний, національний, міжнародний.\n\nМасштаб залежить не лише від кількості глядачів. На нього впливають кількість виконавців, склад творчо-постановочної групи, кількість майданчиків, технічна складність, тривалість і загальний обсяг постановочного процесу.\n\nЗа потреби зазначте орієнтовну кількість виконавців, інших учасників і глядачів. Коротко поясніть, чому саме так визначаєте масштаб проєкту.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"projectVenue","type":"text","title":"1.2.5. Простір / майданчик проведення","help":"Вкажіть реальний або передбачуваний майданчик, у якому має відбуватися проєкт.","placeholder":"Назва або тип майданчика, місто, локація","theory":"Простір / майданчик проведення - це конкретне фізичне середовище, у якому має відбуватися проєкт. Це може бути театральна сцена, концертний зал, клубний простір, площа, вулиця, стадіон, парк, музей, павільйон, виробничий або інший нетрадиційний простір.\n\nНа цьому етапі потрібно визначити саме реальний або передбачуваний майданчик. Художнє осмислення простору буде розглядатися пізніше в режисерському задумі.\n\nМайданчик впливає на розміри сценічної дії, розташування глядача, рух виконавців, можливості світла, звуку, відео, декорацій, монтажу, логістики та безпеки. Тому простір потрібно обирати не тільки за зовнішньою привабливістю, а й з огляду на те, чи дозволяє він реально втілити задум.\n\nЯкщо задум створюється спеціально для конкретної локації і суттєво залежить від її архітектури, історії або функції, обов’язково зазначте це.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"projectAudience","type":"textarea","title":"1.2.6. Цільова аудиторія","help":"Коротко визначте, для кого створюється проєкт. Врахуйте не тільки вік, а й інтереси, культурний досвід та мотивацію присутності.","placeholder":"Хто ваш глядач і чому цей проєкт адресований саме йому?","theory":"Цільова аудиторія - це конкретна група людей, для яких створюється проєкт. Визначення аудиторії не повинно обмежуватися лише віком.\n\nПодумайте про соціально-демографічні характеристики, культурний і глядацький досвід, інтереси, мотивацію присутності, очікування від події та можливий спосіб участі. Для одного проєкту глядач залишається спостерігачем, для іншого може активно взаємодіяти з виконавцями або простором.\n\nРежисеру важливо розуміти, хто ці люди, чому вони прийдуть, що вони вже знають про тему, які асоціації та очікування можуть мати і якою може бути їхня емоційна реакція.\n\nЗнання аудиторії надалі впливатиме на мову проєкту, тривалість, темп, способи комунікації, режисерські прийоми і характер взаємодії з глядачем.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"projectDateTime","type":"text","title":"1.2.7. Дата і час проведення","help":"Якщо точні дата і час ще не визначені, вкажіть орієнтовний період проведення.","placeholder":"Наприклад: 07.11.2026, 19:00 або орієнтовно грудень 2026","theory":"Дата і час проведення - це не лише організаційні дані. Для багатьох великих форм вони впливають і на режисерське рішення.\n\nДата може бути пов’язана зі святом, історичною подією, ювілеєм, фестивальним календарем, сезоном або іншим контекстом. Час проведення впливає на використання природного і сценічного світла, відео, атмосферу, погодні умови, транспортну доступність та тривалість перебування глядача.\n\nОсобливо важливими дата і час є для подій у відкритому просторі. Денне і вечірнє дійство на одному майданчику можуть потребувати принципово різних режисерських і технічних рішень.\n\nЯкщо точні дата та час ще не визначені, зазначте орієнтовний період. Його можна буде уточнити пізніше.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"projectDuration","type":"text","title":"1.2.8. Орієнтовна тривалість / хронометраж","help":"Вкажіть передбачувану тривалість усього проєкту. Для складних подій можна додати орієнтовну тривалість основних блоків.","placeholder":"Наприклад: 90 хвилин","theory":"Хронометраж - це передбачувана тривалість усього проєкту. Його варто визначити вже на початку, навіть якщо надалі він буде уточнюватися.\n\nТривалість безпосередньо впливає на композицію, архітектоніку, кількість епізодів і номерів, темпоритм, розподіл кульмінацій, переходи між частинами та здатність аудиторії утримувати увагу.\n\nПроєкт тривалістю 45 хвилин і проєкт тривалістю три години не можуть мати однакову драматургічну організацію. Для фестивалю, свята або багатомайданчикового проєкту важливо визначити не лише загальну тривалість, а й приблизний хронометраж окремих блоків або програм.\n\nНа цьому етапі достатньо реалістичної орієнтовної цифри. Пізніше вона буде уточнюватися разом зі сценарієм і постановочним планом.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."}]};
const RESEARCH_SECTION={"id":"research-materials","title":"1.3. Пошук, дослідження та збір матеріалу","intro":"Після визначення вихідних параметрів проєкту починається дослідницький етап. Ваше завдання не просто накопичити посилання і файли, а зібрати матеріал, який допоможе глибше зрозуміти тему і поступово сформувати режисерський задум. Знайдені факти, документи, тексти, музика, зображення, відео, сценічні приклади та асоціації можуть згодом перетворитися на драматургію, образи, сценарний хід, монтажні зв’язки та інші засоби сценічного вираження. Матеріал доцільно збирати у двох напрямах: документальному та художньому. Паралельно ведіть режисерський блокнот, де фіксуйте власні ідеї, асоціації та можливі способи поєднання знайденого матеріалу. Це робочий накопичувальний етап: він не подається на перевірку. Коли первинна база сформована, студент лише фіксує результат етапу і продовжує поповнювати матеріали надалі.\n\n**Методична підказка.** Теоретичний матеріал можна відкривати за потреби. Він допомагає сформулювати власне рішення, а не підставити готову відповідь.","published":true,"blocks":[{"id":"documentaryMaterials","type":"material_collection","collectionKind":"documentary","title":"1.3.1. Документальний матеріал","help":"Додавайте факти, документи, архівні матеріали, фото, відео, інтерв’ю, спогади, публікації та інші джерела, пов’язані з реальною дійсністю.","theory":"Документальний матеріал пов’язаний із реальною дійсністю і дає режисерові фактичну основу для осмислення теми. Це можуть бути історичні та сучасні факти, архівні документи, листи, щоденники, спогади, інтерв’ю, фотографії, відеозаписи, аудіозаписи, газетні та журнальні публікації, статистика, біографічні відомості, офіційні документи, музейні предмети, артефакти, іконографічні матеріали, матеріали з конкретного місця або середовища.\n\nДокументальний матеріал не слід просто накопичувати. Кожен знайдений факт або документ потрібно осмислювати з позиції майбутньої постановки: що він відкриває в темі, яку суперечність виявляє, який образ або епізод може народити, чи може стати основою тексту, відеофрагмента, сценічної дії або монтажного зіставлення.\n\nРежисер може проводити і власне дослідження: записувати інтерв’ю, фотографувати місце, працювати з архівами, музеями, приватними колекціями, збирати усні історії та свідчення. Відібрані факти і документи надалі можуть бути образно переосмислені і перетворені на факти мистецтва: драматургію, сценарний хід, сценічний образ, персонажа, звук, відео або інший художній засіб.\n\nДо кожного матеріалу обов’язково залишайте режисерську нотатку: як саме його можна використати або з чим його можна поєднати.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"artisticMaterials","type":"material_collection","collectionKind":"artistic","title":"1.3.2. Художній матеріал","help":"Збирайте твори та фрагменти мистецтва, які можуть стати змістовим, образним, музичним, пластичним або візуальним матеріалом майбутнього проєкту.","theory":"Художній матеріал уже є результатом мистецького осмислення дійсності. До нього належать літературні твори, поезія, драматургія, музика, пісні, кінематограф, фотографія, живопис, хореографія, сценічні номери, вистави, сценографія, костюм, звукові та відеоматеріали, а також інші твори різних видів мистецтва.\n\nСценарний матеріал великого видовищного проєкту може бути художнім, літературним, образотворчим, звуковим і музичним. Джерелом можуть стати як цілі твори, так і окремі фрагменти, образи, мотиви, фактури, ритми, інтонації, принципи побудови або режисерські прийоми.\n\nВажливо не копіювати знайдене рішення, а зрозуміти, що саме в ньому вас цікавить. Це може бути музична тема, спосіб появи виконавця, пластичний принцип, колір, композиція кадру, характер монтажу, сценографічний образ, контраст, ритм або спосіб взаємодії з глядачем.\n\nДо кожного художнього матеріалу фіксуйте, що саме вас зацікавило і як цей матеріал може працювати у вашому проєкті: стати основою епізоду, створити атмосферу, вступити в контраст із документом, підказати образ, просторове рішення або принцип монтажу.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"directorNotebook","type":"material_collection","collectionKind":"notes","title":"1.3.3. Режисерський блокнот","help":"Фіксуйте ідеї одразу, коли вони виникають. Тут можуть з’являтися образи, монтажні зв’язки, просторові рішення, питання, музичні та візуальні задуми.","theory":"Режисерський блокнот потрібен для того, щоб не втрачати думки, які виникають під час дослідження. Не кожна ідея одразу належить до конкретного документа чи твору. Іноді спочатку з’являється образ, фраза, ритм, спосіб переходу між епізодами, поєднання двох матеріалів або питання, на яке ще немає відповіді.\n\nФіксуйте такі думки одразу. Вони не зобов’язані бути остаточними або правильними. Це робочий простір режисера. Тут можна записати, як поєднати архівний документ із музикою, яким може бути пролог, який предмет може стати образом, де використати тишу, як змінити простір, як підвести глядача до певного переживання.\n\nОсобливо важливо фіксувати зв’язки між матеріалами. Саме в таких зв’язках часто починає народжуватися монтаж, епізод, сценарно-режисерський хід або майбутній художній образ.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."}]};
const IDEOLOGICAL_ANALYSIS_SECTION={"id":"ideological-analysis","title":"1.4. Ідейно-тематичний аналіз","intro":"**Ідейно-тематичний аналіз** формує смисловий і дієвий центр майбутнього проєкту. На цьому етапі режисер не просто називає тему, а вибудовує внутрішню логіку задуму: від проблеми, що потребує осмислення, до теми, через яку вона розкривається; від авторської ідеї до надзавдання; від конфлікту до наскрізної дії.\n\n**Важливо:** усі елементи мають стосуватися одного й того самого смислового ядра. Якщо проблема, тема, ідея, конфлікт і наскрізна дія існують окремо один від одного, задум ще не сформований.","published":true,"blocks":[{"id":"ideologicalLogic","type":"logic_chain","title":"Логіка ідейно-тематичного аналізу","help":"Не сприймайте ці пункти як окремі відповіді. Вони мають послідовно виростати один з одного.","chain":[{"label":"ПРОБЛЕМА","question":"Що потребує осмислення?"},{"label":"ТЕМА","question":"Через яке коло явищ я це досліджую?"},{"label":"ІДЕЯ","question":"Яку авторську думку я стверджую?"},{"label":"НАДЗАВДАННЯ","question":"Заради чого я створюю цей проєкт?"},{"label":"КОНФЛІКТ","question":"Які сили вступають у боротьбу і за що?"},{"label":"НАСКРІЗНА ДІЯ","question":"Яким дієвим шляхом проєкт рухається до надзавдання?"}],"note":"**Проблема ставить питання. Тема визначає площину його дослідження. Ідея формулює авторську відповідь. Надзавдання визначає режисерську мету. Конфлікт створює боротьбу. Наскрізна дія організовує цю боротьбу в єдиний рух до надзавдання.**"},{"id":"problem","type":"textarea","title":"1.4.1. Проблема","help":"Сформулюйте головне питання, суперечність або явище, яке потребує осмислення і лежить в основі майбутнього проєкту.","placeholder":"Яке питання або суперечність є вихідною для мого проєкту?","theory":"**Проблема** - це вихідне смислове питання або суперечність, яка потребує осмислення і спонукає режисера до створення проєкту. Вона задає найширше поле, з якого далі виростають тема, ідея, конфлікт і надзавдання.\n\nПроблема не повинна бути просто назвою явища: «самотність», «пам’ять», «війна», «покоління». Такі слова лише позначають сферу. Режисерська проблема виникає тоді, коли в цій сфері виявляється питання, суперечність або напруга, що потребує відповіді.\n\nНаприклад: не «культурна пам’ять», а **«чому суспільство втрачає зв’язок із власною культурною пам’яттю?»**; не «самотність», а **«чому людина може залишатися самотньою навіть серед інших?»**.\n\nПроблема може мати соціальний, моральний, культурний, психологічний, історичний або особистісний характер. Головне - щоб вона була реальною вихідною суперечністю саме вашого задуму, а не абстрактною «важливою темою»."},{"id":"theme","type":"textarea","title":"1.4.2. Тема","help":"Визначте конкретне коло життєвих явищ, подій і відносин, через яке у вашому проєкті розкриватиметься проблема.","placeholder":"Через які саме явища, події, постаті або відносини я досліджую проблему?","theory":"**Тема** - це конкретне коло життєвих явищ, подій, постатей і відносин, через яке режисер досліджує обрану проблему. Якщо проблема відповідає на питання **«що потребує осмислення?»**, то тема - **«через що саме я буду це осмислювати?»**.\n\nОдна проблема може бути розкрита через різні теми. Наприклад, проблему втрати ідентичності можна досліджувати через родинну пам’ять, мову, музику певного покоління, еміграцію, історичні травми або міський простір.\n\nТема має бути конкретнішою за проблему і безпосередньо пов’язаною з матеріалом майбутнього проєкту. Вона не є слоганом і не повинна підмінятися ідеєю. **Тема окреслює предмет художнього дослідження, але ще не формулює авторську оцінку цього матеріалу.**"},{"id":"idea","type":"textarea","title":"1.4.3. Ідея","help":"Сформулюйте головну авторську думку, що народжується з осмислення проблеми через обрану тему.","placeholder":"Що саме я стверджую цим проєктом?","theory":"**Ідея** - це головна авторська думка, висновок і позиція режисера щодо проблеми, яку він досліджує через тему. Якщо проблема ставить питання, а тема визначає матеріал дослідження, то ідея формулює **авторську відповідь**.\n\nІдея повинна містити завершену думку, а не загальне гасло на кшталт «треба бути добрими», «важливо пам’ятати історію» або «любов перемагає все». Важливо зрозуміти, **що саме ви доводите своїм проєктом і в чому полягає ваша позиція**.\n\nДля пошуку формулювання можна тимчасово використати конструкції **«Я переконаний, що…»**, **«Я хочу довести, що…»**, **«Для мене важливо ствердити, що…»**, а потім прибрати цей вступ і залишити саму думку.\n\nНаприклад: проблема - байдужість до культурної пам’яті; тема - присутність творчості митців минулого в сучасній культурі; ідея - **культурна пам’ять залишається живою лише тоді, коли кожне покоління переосмислює її заново.**"},{"id":"supertask","type":"textarea","title":"1.4.4. Надзавдання (мета)","help":"Визначте головну режисерську мету: заради чого ви розкриваєте цю проблему через обрану тему та утверджуєте ідею.","placeholder":"Заради чого я створюю цей проєкт і до якого осмислення або переживання хочу привести глядача?","theory":"**Надзавдання** - це головна режисерська мета, заради якої створюється проєкт. Воно визначає, **до якого осмислення, переживання, зміни ставлення або внутрішньої дії режисер прагне привести глядача**.\n\nПроблема визначає, що потребує осмислення. Тема - через який матеріал це буде розкрито. Ідея - що режисер стверджує. **Надзавдання відповідає на питання: заради чого я все це роблю?**\n\nІдея і надзавдання взаємопов’язані, але не тотожні: **ідея є авторським твердженням, надзавдання - спрямованістю режисерської дії на глядача.**\n\nДоцільно формулювати надзавдання через активну дію: **спонукати, пробудити, переконати, змусити замислитися, допомогти усвідомити, викликати потребу, повернути увагу**. Наприклад: **спонукати глядача відчути особисту відповідальність за збереження і продовження культурної пам’яті.**"},{"id":"conflict","type":"conflict_builder","title":"1.4.5. Конфлікт","help":"Визначте головне зіткнення: зміст конфлікту, його сторони, предмет боротьби та конкретні прояви обох сторін у матеріалі проєкту.","theory":"**Конфлікт** - це зіткнення протилежних прагнень, позицій, цінностей, явищ або сил, яке виникає з тієї самої проблеми й приводить сценічну дію в рух.\n\nКонфлікт не слід вигадувати окремо від проблеми, теми та ідеї. Якщо попередні пункти говорять про одне, а конфлікт - про інше, смислова логіка проєкту розпадається.\n\nДля головного конфлікту потрібно визначити: **зміст конфлікту** - що з чим стикається; **сторони конфлікту** - хто або що представляє протилежні сили; **предмет конфлікту** - за що фактично ведеться боротьба.\n\nУ видовищних формах сторонами конфлікту не обов’язково є персонажі. Це можуть бути цінності, позиції, способи мислення або явища: пам’ять і забуття, особистий вибір і суспільний тиск, гідність і приниження, людина і власний страх.\n\nАле абстрактного формулювання недостатньо. Кожна сторона має бути **проявлена у конкретному сценічному матеріалі**: через факти, історії, документи, номери, персонажів, реальних героїв, тексти, відео, музику, образи чи події. Саме тоді теоретичний конфлікт перетворюється на основу сценічної дії."},{"id":"throughAction","type":"textarea","title":"1.4.6. Наскрізна дія","wide":true,"rows":6,"help":"Сформулюйте головний дієвий вектор, який виростає з конфлікту, проходить через увесь проєкт і веде до реалізації надзавдання.","placeholder":"Якою дією я послідовно веду проєкт від початку до реалізації надзавдання?","theory":"**Наскрізна дія** - це основна лінія боротьби, головний дієвий шлях до надзавдання, що проходить через увесь проєкт і об’єднує його події та епізоди в цілісний рух.\n\nВона виростає з конфлікту і не є просто «червоною ниткою», темою або повторюваним образом. Наскрізна дія відповідає на питання: **що ми послідовно робимо протягом усього проєкту, долаючи протидію, щоб привести глядача до надзавдання?**\n\nФормулювати її варто **через дію**, а не через абстрактний стан: не «пам’ять поколінь», а **«повертати забуті голоси в сучасність»**; не «боротьба за свободу», а **«відстоювати право на власний вибір»**.\n\nНаскрізна дія є робочим режисерським орієнтиром. На наступних етапах вона повинна проявитися у подієвому ряді, композиції, архітектоніці та сценарному плані. Якщо ці елементи не підтримують сформульований дієвий вектор, до наскрізної дії потрібно повернутися й уточнити її."},{"id":"ideologicalCheck","type":"logic_chain","title":"Перевірка цілісності задуму","help":"Перевірте не окремі формулювання, а причинно-наслідковий зв’язок між ними.","chain":[{"label":"ПРОБЛЕМА","question":"Яке питання лежить в основі задуму?"},{"label":"ТЕМА","question":"Через який матеріал воно досліджується?"},{"label":"ІДЕЯ","question":"Яку авторську відповідь я даю?"},{"label":"НАДЗАВДАННЯ","question":"До чого прагну привести глядача?"},{"label":"КОНФЛІКТ","question":"Які сили створюють боротьбу?"},{"label":"НАСКРІЗНА ДІЯ","question":"Яким дієвим шляхом ця боротьба веде до надзавдання?"}],"note":"Якщо один із пунктів можна без втрат замінити випадковим формулюванням або він не впливає на наступний, зв’язок ще недостатньо точний. **У сильному задумі кожен наступний елемент виростає з попереднього.**"}]};
const SCENARIO_PLOT_SECTION={"id":"scenario-plot","title":"2.1. Сюжет","intro":"**Сюжет** - система подій, перебіг дії та послідовність її розвитку. У різних сценічних формах сюжет існує по-різному: у сюжетній виставі це може бути історія персонажів, а у концерті, церемонії, конкурсі, фестивалі, вечорі чи іншій номерній формі - послідовна історія того, що реально відбувається перед глядачем від початку до завершення.\n\n**Методична підказка.** Теоретичний матеріал можна відкривати за потреби. Він допомагає сформулювати власне рішення, а не підставити готову відповідь.","published":true,"chapter":2,"chapterTitle":"СЦЕНАРНО-ДРАМАТУРГІЧНА ОСНОВА","chapterStart":true,"blocks":[{"id":"dramaturgyPlot","type":"textarea","title":"Розгорнутий сюжет проєкту","wide":true,"rows":14,"help":"Опишіть послідовну історію майбутнього проєкту від початку до завершення. Для сюжетної форми - що відбувається з персонажами. Для концертної або номерної форми - що буквально відбувається на майданчику, хто з'являється, які сценічні одиниці виникають, у чому їхній зміст і що відбувається далі.","placeholder":"Опишіть майбутній проєкт як послідовність подій від початку до завершення...","theory":"**Сюжет** - система подій, перебіг дії та послідовність її розвитку, в ході яких розкриваються характери персонажів і головна ідея. Сюжет показує, **що саме відбувається і в якій послідовності це бачить глядач**.\n\nУ **виставі, шоу-виставі або іншій сюжетній формі** сюжет може бути повноцінною історією персонажів. Наприклад: героїня приїздить до іншого міста, зустрічає людину, яка змінює її плани, між ними виникає суперечність, герої приймають рішення, події загострюються і приводять до кульмінації та розв'язки. Тут важливо розповісти не тему твору, а **що конкретно відбувається з героями**.\n\nУ **концерті, церемонії, конкурсі, фестивалі, вечорі або іншій номерній формі** сюжет - це історія самого проєкту, тобто послідовність подій, які реально відбуваються перед глядачем. Наприклад: глядачі входять до зали, починається вступна сценічна дія, з'являється ведучий, відкривається певна інформація, відбувається номер, після нього виникає наступна подія, далі інша сценічна одиниця змінює напрям розвитку дії і так до завершення.\n\nУ такій формі важливо описувати **не сухий перелік номерів**, а те, як розгортається подія: хто прийшов або з'явився, де відбувається дія, що бачить глядач, що відкривається на сцені, який номер або інша одиниця сценічної інформації виникає, у чому її зміст, що вона змінює і що відбувається після неї.\n\nОтже, сюжет може мати різну природу, але завжди відповідає на питання: **що відбувається від початку до завершення і як одна подія приводить до наступної?**\n\n**Приклад із практики.** Уявіть гала-концерт без персонажного сюжету. Спробуйте визначити подієву лінію: очікування зустрічі, відкриття різних сторін творчості, несподіване об’єднання артистів у фіналі. Важливо не просто назвати елементи, а показати їхню роль у конкретному режисерському рішенні.\n\n**Як виконувати цей пункт.** Спочатку дайте відповідь на головне питання поля одним або двома реченнями. Потім обґрунтуйте її конкретними обставинами, діями, матеріалами чи сценічними засобами. Завершіть поясненням, як це рішення пов’язане із загальним задумом. Якщо пункт оформлено таблицею, заповнюйте кожен рядок стосовно відповідної структурної одиниці, а не повторюйте загальне формулювання.\n\n**Приклад слабкої та вдалої відповіді.** Недостатньо: «Буде красиво, сучасно й цікаво». Краще: назвати конкретну сценічну подію, описати спосіб її організації та пояснити, яке значення вона матиме для глядача.\n\n**Перевірте себе.** Чи зрозуміло з моєї відповіді, що саме відбуватиметься? Чому я обрав таке рішення? Чи не повторюю текст із сусіднього пункту? Чи зможе інший учасник постановочної групи уявити мій задум?\n\n**Типові помилки.** Загальні фрази без прикладів; підміна художнього рішення переліком обладнання; механічне копіювання визначення з теорії; опис бажаного ефекту без способу його досягнення.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."}]};
const SCENARIO_COMPOSITION_SECTION={"id":"scenario-composition","title":"2.2. Композиція","intro":"**Композиція** - це внутрішня побудова твору, співвідношення всіх його компонентів, що створює цілісний художній твір та сприяє виявленню головної ідеї. **Усі складові композиції потрібно розписати по подіях.**\n\n**Методична підказка.** Теоретичний матеріал можна відкривати за потреби. Він допомагає сформулювати власне рішення, а не підставити готову відповідь.","published":true,"chapter":2,"chapterTitle":"СЦЕНАРНО-ДРАМАТУРГІЧНА ОСНОВА","blocks":[{"id":"compositionIntro","type":"logic_chain","title":"Формула композиції","help":"Композиція розкладає розвиток дії та конфлікту на основні етапи.","chain":[{"label":"ЕКСПОЗИЦІЯ","question":"Де, коли, з ким починаються події?"},{"label":"ЗАВ'ЯЗКА","question":"Яка подія порушує рівновагу і запускає конфлікт?"},{"label":"РОЗВИТОК ДІЇ","question":"Як по подіях розвиваються дія і конфлікт?"},{"label":"КУЛЬМІНАЦІЯ","question":"Де конфлікт досягає найвищої напруги?"},{"label":"РОЗВ'ЯЗКА","question":"Як завершується розвиток подій і вирішується конфлікт?"}],"note":"**Експозиція → зав'язка → розвиток дії → кульмінація → розв'язка.** Усі складові описуйте через конкретні події одного й того самого проєкту."},{"id":"compositionExposition","type":"textarea","title":"2.2.1. Експозиція","wide":true,"rows":7,"help":"Опишіть початкову частину по конкретних подіях: де, коли і з ким усе починається, що бачить і дізнається глядач, яка атмосфера створюється.","placeholder":"Які конкретні події формують експозицію?","theory":"**Експозиція** - початкова частина твору, у якій ми дізнаємось **де? коли? з ким?** трапляються події. Знайомимося із місцем дії, головними героями, учасниками або вихідною ситуацією. Експозиція створює певну емоційну атмосферу майбутньої дії та переростає у зав'язку.\n\nУ номерних і концертних формах експозицією так само є конкретні початкові події: вхід або поява глядача у певному просторі, вступна дія, відео, музичний пролог, поява ведучого, перший номер або інша сценічна інформація, яка вводить у тему та обставини проєкту.\n\n**Розписуйте експозицію по подіях, а не тільки визначенням.**\n\n**Приклад із практики.** Уявіть церемонію нагородження. Спробуйте визначити експозицію через представлення події, зав’язку через оголошення номінації, розвиток очікування, кульмінацію оголошення переможця та завершення. Важливо не просто назвати елементи, а показати їхню роль у конкретному режисерському рішенні.\n\n**Як виконувати цей пункт.** Спочатку дайте відповідь на головне питання поля одним або двома реченнями. Потім обґрунтуйте її конкретними обставинами, діями, матеріалами чи сценічними засобами. Завершіть поясненням, як це рішення пов’язане із загальним задумом. Якщо пункт оформлено таблицею, заповнюйте кожен рядок стосовно відповідної структурної одиниці, а не повторюйте загальне формулювання.\n\n**Приклад слабкої та вдалої відповіді.** Недостатньо: «Буде красиво, сучасно й цікаво». Краще: назвати конкретну сценічну подію, описати спосіб її організації та пояснити, яке значення вона матиме для глядача.\n\n**Перевірте себе.** Чи зрозуміло з моєї відповіді, що саме відбуватиметься? Чому я обрав таке рішення? Чи не повторюю текст із сусіднього пункту? Чи зможе інший учасник постановочної групи уявити мій задум?\n\n**Типові помилки.** Загальні фрази без прикладів; підміна художнього рішення переліком обладнання; механічне копіювання визначення з теорії; опис бажаного ефекту без способу його досягнення.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"compositionInciting","type":"textarea","title":"2.2.2. Зав'язка","wide":true,"rows":7,"help":"Назвіть конкретну подію або ряд подій, які стають причиною конфлікту, порушують початкову рівновагу і запускають розвиток дії.","placeholder":"Яка конкретна подія є зав'язкою?","theory":"**Зав'язка** - подія або ряд подій, що служать причиною конфлікту. **Зав'язка - перша подія, яка порушує рівновагу в дії.** Це момент у творі, після якого стає цікаво, що ж буде далі.\n\nУ різних формах зав'язкою може бути вчинок персонажа, поява нової обставини, оголошення правила або результату, відкриття факту, документ, номер, репліка ведучого, зміна ситуації чи інша подія, яка запускає головний рух проєкту.\n\n**Назвіть саме подію, а не загальний стан або тему.**\n\n**Приклад із практики.** Уявіть церемонію нагородження. Спробуйте визначити експозицію через представлення події, зав’язку через оголошення номінації, розвиток очікування, кульмінацію оголошення переможця та завершення. Важливо не просто назвати елементи, а показати їхню роль у конкретному режисерському рішенні.\n\n**Як виконувати цей пункт.** Спочатку дайте відповідь на головне питання поля одним або двома реченнями. Потім обґрунтуйте її конкретними обставинами, діями, матеріалами чи сценічними засобами. Завершіть поясненням, як це рішення пов’язане із загальним задумом. Якщо пункт оформлено таблицею, заповнюйте кожен рядок стосовно відповідної структурної одиниці, а не повторюйте загальне формулювання.\n\n**Приклад слабкої та вдалої відповіді.** Недостатньо: «Буде красиво, сучасно й цікаво». Краще: назвати конкретну сценічну подію, описати спосіб її організації та пояснити, яке значення вона матиме для глядача.\n\n**Перевірте себе.** Чи зрозуміло з моєї відповіді, що саме відбуватиметься? Чому я обрав таке рішення? Чи не повторюю текст із сусіднього пункту? Чи зможе інший учасник постановочної групи уявити мій задум?\n\n**Типові помилки.** Загальні фрази без прикладів; підміна художнього рішення переліком обладнання; механічне копіювання визначення з теорії; опис бажаного ефекту без способу його досягнення.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"compositionDevelopment","type":"textarea","title":"2.2.3. Розвиток дії","wide":true,"rows":18,"help":"Це найбільш масштабна частина композиції. Розпишіть по подіях увесь шлях від зав'язки до кульмінації: що відбувається, як змінюється ситуація, як розвивається конфлікт, як наростає дія і як одна подія породжує наступну.","placeholder":"Подія 1: ...\nПодія 2: ...\nПодія 3: ...\nПояснюйте, що змінюється після кожної події і як розвивається конфлікт.","theory":"**Розвиток дії розписується по подіях.**\n\n**Розвиток дії** - події від зав'язки до кульмінації, в яких відбувається розвиток драматичної дії твору, тобто **розвиток конфлікту**.\n\nРозвиток дії має свої закономірності: **сувора лаконічність побудови і розвитку теми, наростання дії, завершеність кожної окремої частини дії.**\n\nЦе не короткий переказ одним абзацом. Послідовно опишіть усі основні події: що відбулося, що змінилося після цього, як реагують сторони конфлікту, які нові обставини виникають, як наростає напруга і чому наступна подія стає наслідком попередньої.\n\nУ номерній формі розвиток дії так само складається з конкретних сценічних подій: виходів ведучих, номерів, документів, відео, фактів, конкурсних етапів, нагороджень, змін простору, появи нової інформації та інших сценічних одиниць, якщо вони реально рухають дію і розвивають конфлікт.\n\n**Цей пункт має бути одним із найдетальніших у всій сценарно-драматургічній основі.**\n\n**Приклад із практики.** Уявіть церемонію нагородження. Спробуйте визначити експозицію через представлення події, зав’язку через оголошення номінації, розвиток очікування, кульмінацію оголошення переможця та завершення. Важливо не просто назвати елементи, а показати їхню роль у конкретному режисерському рішенні.\n\n**Як виконувати цей пункт.** Спочатку дайте відповідь на головне питання поля одним або двома реченнями. Потім обґрунтуйте її конкретними обставинами, діями, матеріалами чи сценічними засобами. Завершіть поясненням, як це рішення пов’язане із загальним задумом. Якщо пункт оформлено таблицею, заповнюйте кожен рядок стосовно відповідної структурної одиниці, а не повторюйте загальне формулювання.\n\n**Приклад слабкої та вдалої відповіді.** Недостатньо: «Буде красиво, сучасно й цікаво». Краще: назвати конкретну сценічну подію, описати спосіб її організації та пояснити, яке значення вона матиме для глядача.\n\n**Перевірте себе.** Чи зрозуміло з моєї відповіді, що саме відбуватиметься? Чому я обрав таке рішення? Чи не повторюю текст із сусіднього пункту? Чи зможе інший учасник постановочної групи уявити мій задум?\n\n**Типові помилки.** Загальні фрази без прикладів; підміна художнього рішення переліком обладнання; механічне копіювання визначення з теорії; опис бажаного ефекту без способу його досягнення.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"compositionClimax","type":"textarea","title":"2.2.4. Кульмінація","wide":true,"rows":6,"help":"Назвіть конкретну подію, у якій конфлікт і психологічне напруження досягають найвищої точки.","placeholder":"Яка конкретна подія є найвищою точкою розвитку конфлікту?","theory":"**Кульмінація** - найвища точка розвитку психологічного напруження; подія, в якій відбувається **точка найвищої напруги конфлікту**; найбільш концентроване вираження ідеї постановки.\n\nКульмінація - це не автоматично найгучніший, наймасовіший або технічно найскладніший номер. Вона визначається тим, **де саме головний конфлікт досягає максимальної напруги і відбувається вирішальна подія**.\n\n**Приклад із практики.** Уявіть церемонію нагородження. Спробуйте визначити експозицію через представлення події, зав’язку через оголошення номінації, розвиток очікування, кульмінацію оголошення переможця та завершення. Важливо не просто назвати елементи, а показати їхню роль у конкретному режисерському рішенні.\n\n**Як виконувати цей пункт.** Спочатку дайте відповідь на головне питання поля одним або двома реченнями. Потім обґрунтуйте її конкретними обставинами, діями, матеріалами чи сценічними засобами. Завершіть поясненням, як це рішення пов’язане із загальним задумом. Якщо пункт оформлено таблицею, заповнюйте кожен рядок стосовно відповідної структурної одиниці, а не повторюйте загальне формулювання.\n\n**Приклад слабкої та вдалої відповіді.** Недостатньо: «Буде красиво, сучасно й цікаво». Краще: назвати конкретну сценічну подію, описати спосіб її організації та пояснити, яке значення вона матиме для глядача.\n\n**Перевірте себе.** Чи зрозуміло з моєї відповіді, що саме відбуватиметься? Чому я обрав таке рішення? Чи не повторюю текст із сусіднього пункту? Чи зможе інший учасник постановочної групи уявити мій задум?\n\n**Типові помилки.** Загальні фрази без прикладів; підміна художнього рішення переліком обладнання; механічне копіювання визначення з теорії; опис бажаного ефекту без способу його досягнення.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."},{"id":"compositionResolution","type":"textarea","title":"2.2.5. Розв'язка","wide":true,"rows":7,"help":"Опишіть конкретну подію або ряд подій, що завершують розвиток подій і вирішують головний конфлікт.","placeholder":"Якими подіями завершується розвиток і вирішується конфлікт?","theory":"**Розв'язка** - завершення розвитку подій, вирішення конфлікту, засіб надання уявлення про задум автора, підкреслення цінності ідей, принципів, закладених у постановці.\n\nОпишіть, **що конкретно відбувається після кульмінації**, як завершується боротьба, що стає зрозумілим глядачеві і до якого нового стану приходять персонажі, учасники, тема або вся подія.\n\n**Приклад із практики.** Уявіть церемонію нагородження. Спробуйте визначити експозицію через представлення події, зав’язку через оголошення номінації, розвиток очікування, кульмінацію оголошення переможця та завершення. Важливо не просто назвати елементи, а показати їхню роль у конкретному режисерському рішенні.\n\n**Як виконувати цей пункт.** Спочатку дайте відповідь на головне питання поля одним або двома реченнями. Потім обґрунтуйте її конкретними обставинами, діями, матеріалами чи сценічними засобами. Завершіть поясненням, як це рішення пов’язане із загальним задумом. Якщо пункт оформлено таблицею, заповнюйте кожен рядок стосовно відповідної структурної одиниці, а не повторюйте загальне формулювання.\n\n**Приклад слабкої та вдалої відповіді.** Недостатньо: «Буде красиво, сучасно й цікаво». Краще: назвати конкретну сценічну подію, описати спосіб її організації та пояснити, яке значення вона матиме для глядача.\n\n**Перевірте себе.** Чи зрозуміло з моєї відповіді, що саме відбуватиметься? Чому я обрав таке рішення? Чи не повторюю текст із сусіднього пункту? Чи зможе інший учасник постановочної групи уявити мій задум?\n\n**Типові помилки.** Загальні фрази без прикладів; підміна художнього рішення переліком обладнання; механічне копіювання визначення з теорії; опис бажаного ефекту без способу його досягнення.\\n\\n**Приклад для сценічного проєкту.** Наприклад, у концерті одна сценічна одиниця може виконувати іншу художню функцію, ніж у церемонії нагородження. Поясніть особливості саме вашої форми.\\n\\n**Що саме вписувати.** Запишіть конкретне рішення для власного проєкту і поясніть, як його можна побачити або перевірити на сцені."}]};
const SCENARIO_ARCHITECTURE_SECTION={"id":"scenario-architecture","title":"2.3. Архітектоніка","intro":"**Архітектоніка** - це зовнішня конструкція сценічного твору: з яких структурних одиниць він складається, як ці одиниці групуються та в якій послідовності розташовані. На цьому етапі ми фіксуємо саме **будову проєкту**, а не розписуємо драматургічне наповнення кожної частини - воно з’явиться у сценарному плані.","published":true,"chapter":2,"chapterTitle":"СЦЕНАРНО-ДРАМАТУРГІЧНА ОСНОВА","blocks":[{"id":"architectureOverview","type":"textarea","title":"2.3.1. Загальна характеристика архітектоніки","wide":true,"rows":6,"help":"Сформулюйте загальний принцип побудови проєкту: номерний, епізодний або комбінований. Вкажіть, чи має проєкт вступну частину, великі епізоди / блоки, фінал і за яким принципом окремі номери чи інші сценічні одиниці об’єднуються у більші частини.","placeholder":"Наприклад: проєкт має комбіновану побудову… Матеріал об’єднано у три епізоди за принципом… Вступна частина… Фінал…","theory":"**Архітектоніка** показує зовнішню будову сценічного твору. Вона відповідає на питання: **з яких частин складається проєкт і як вони організовані між собою?**\n\nНе плутайте архітектоніку з композицією. **Композиція** показує внутрішній розвиток дії - експозицію, зав’язку, розвиток дії, кульмінацію та розв’язку. **Архітектоніка** показує зовнішню конструкцію - вступ, епізоди, блоки, номери, переходи між великими частинами, фінал та їхню послідовність.\n\nУ сценічних проєктах можна умовно виділити кілька моделей побудови:\n\n- **номерна** - твір складається переважно з відносно самостійних номерів або інших сценічних одиниць;\n- **епізодна** - матеріал об’єднано у великі смислові частини / епізоди, всередині яких розташовані окремі одиниці;\n- **комбінована** - поєднує обидва принципи: наприклад, вступ, кілька великих епізодів із номерами всередині та фінал.\n\nНе кожен проєкт обов’язково повинен мати «інтро - три епізоди - фінал». Кількість і тип частин визначаються формою, драматургією та матеріалом конкретного задуму.\n\n**Що заповнювати у цьому полі.** Коротко опишіть саме **загальну модель будови** вашого проєкту: як він структурований, які великі частини має і за яким принципом матеріал об’єднується в ці частини. Тут не потрібно переказувати зміст кожного номера чи описувати постановочні рішення."},{"id":"architectureStructure","type":"architecture_builder","title":"2.3.2. Архітектонічна структура проєкту","wide":true,"help":"У таблиці фіксується тільки архітектонічна структура: **№, структурна одиниця, назва**. Оберіть тип одиниці (наприклад, інтро, епізод, номер, фінал або власний варіант) і дайте їй назву. Нумерацію система формує автоматично.","theory":"Ця таблиця є **каркасом проєкту**. Вона показує послідовність і вкладеність структурних одиниць, з яких складається майбутній твір.\n\nУ таблиці є лише три графи:\n\n- **№** - формується системою автоматично;\n- **Структурна одиниця** - вкажіть, чим є цей рядок у будові твору: інтро, епізод, номер, фінал або інша доречна одиниця;\n- **Назва** - робоча або остаточна назва цієї структурної одиниці.\n\nЯкщо епізод містить кілька номерів чи інших одиниць, система показує їх як вкладені рядки з нумерацією на кшталт 1.1, 1.2, 1.3.\n\n**Важливо:** у цій таблиці **немає графи «опис», «функція» чи «драматургічна розробка»**. Не потрібно намагатися вписати їх у назву. Що саме відбувається в кожній одиниці, її драматургічне наповнення, монтажний зв’язок і хронометраж ви розробляєте далі у **сценарному плані**."}]};
const SCENARIO_PLAN_SECTION={"id":"scenario-plan","title":"2.5. Сценарний план","intro":"**Сценарний план** розгортає архітектонічний каркас у драматургічну структуру. Рядки **№, структурна одиниця і назва** є спільними з архітектонікою. До них додаються три робочі графи: **сценарна / драматургічна розробка, монтажний прийом і хронометраж**.","published":true,"chapter":2,"chapterTitle":"СЦЕНАРНО-ДРАМАТУРГІЧНА ОСНОВА","blocks":[{"id":"scenarioPlan","type":"scenario_linked","title":"Сценарний план","wide":true,"help":"Заповнюйте рядок відповідно до реальних граф таблиці. У «Сценарній / драматургічній розробці» коротко зафіксуйте, що відбувається в цій одиниці та що вона змінює у розвитку твору. У «Монтажному прийомі» вкажіть принцип її зв’язку з попередньою одиницею. У «Хронометражі» зазначте орієнтовну тривалість.","theory":"**Сценарний план** - це робоча схема драматургічного розгортання майбутнього сценічного твору. Він спирається на вже створену архітектоніку, але додає зміст кожної одиниці, спосіб її монтажного зв’язку та час.\n\nТаблиця містить такі графи:\n\n- **№** - нумерація структурних одиниць; система формує її автоматично;\n- **Структурна одиниця** - спільна з архітектонікою: інтро, епізод, номер, фінал або інший тип;\n- **Назва** - назва цієї одиниці; вона також спільна з архітектонікою;\n- **Сценарна / драматургічна розробка** - коротко й конкретно опишіть, **що відбувається в цій одиниці**: яка подія, дія, номер, текстовий, музичний, документальний чи інший матеріал виникає; що відкривається або змінюється для глядача; як ця одиниця просуває розвиток дії, конфлікту чи основної думки;\n- **Монтажний прийом** - зазначте, **яким способом ця одиниця поєднується з попередньою**: послідовно, контрастно, паралельно, асоціативно, через лейтмотив, ретроспекцію або інший прийом. Для першої одиниці можна залишити графу порожньою або зазначити «початок»;\n- **Хронометраж** - орієнтовна тривалість конкретної одиниці. Загальний хронометраж система підраховує автоматично.\n\n**Різниця між архітектонікою і сценарним планом:** архітектоніка показує **каркас** - які частини є і в якій послідовності. Сценарний план показує **драматургічне наповнення цього каркаса**.\n\n**Різниця між сценарним планом і режисерською експлікацією:** у сценарному плані ще не потрібно детально описувати мізансцени, світлові команди, сценографічні трансформації, роботу камер або технічні cue. Це вже рівень конкретного режисерського та постановочного рішення.\n\nСценарна / драматургічна розробка не повинна бути ані одним загальним словом, ані повним літературним сценарієм. Її завдання - дати достатньо інформації, щоб було зрозуміло **що відбувається, навіщо ця одиниця існує в розвитку твору і як вона переходить у наступну**."}]};
const DIRECTOR_IMAGE_SECTION={"id":"director-image","title":"3.1. Загальносценічний образ","intro":"Три взаємопов’язані складові єдиного художнього задуму. Для кожного пункту доступні докладна теорія та необов’язкові матеріали / посилання. Атмосфера, темпоритм і сценографія розкриваються у своїх підрозділах.","published":true,"chapter":3,"chapterTitle":"РЕЖИСЕРСЬКИЙ ЗАДУМ","chapterStart":true,"blocks":[{"id":"stageImageSynthesis","type":"textarea","title":"3.1.1. Загальносценічний образ","wide":true,"rows":7,"help":"Сформулюйте цілісний художній образ, його зміст та зв’язок із темою й ідеєю. Атмосфера, темпоритм і сценографія докладно розробляються в інших пунктах.","placeholder":"Я бачу цей проєкт як…","theory":"ЗАГАЛЬНОСЦЕНІЧНИЙ ОБРАЗ\n\n1. Що таке загальносценічний образ?\n\nЗагальносценічний образ  -  це цілісне художнє бачення постановки, яке об’єднує всі її складові в єдиний сценічний світ і допомагає донести до глядача головну думку режисера.\n\nБудь-який сценічний проєкт складається з багатьох елементів: виступів артистів, музики, сценографії, світла, відеоконтенту, костюмів, пластики, сценічної дії тощо. Але сама наявність цих елементів ще не створює цілісного художнього твору.\n\nНаприклад, можна організувати концерт із відомими артистами, якісним звуком, сучасними екранами та ефектним освітленням. Кожен номер може бути професійно поставлений, але загалом концерт сприйматиметься як послідовність окремих виступів.\n\nЗагальносценічний образ допомагає режисеру об’єднати різні елементи постановки спільною художньою логікою.\n\nВін визначає не просто те, як виглядатиме сцена, а те, який художній світ виникне перед глядачем, які асоціації він викликатиме та яке значення матиме для розкриття ідеї проєкту.\n\nНаприклад, режисер створює концерт, присвячений творчості видатного музиканта.\n\nОдин із можливих загальносценічних образів  -  «Жива пам’ять».\n\nЦе означає, що режисер бачить концерт не як звичайне згадування минулого, а як художній простір, у якому творчість людини продовжує існувати в сучасності.\n\nТакий образ може визначати характер сценографії, використання архівних матеріалів, музичне оформлення, світлову атмосферу, взаємодію виконавців із відеозображеннями та загальне емоційне сприйняття концерту.\n\nВодночас «Жива пам’ять»  -  це ще не готове постановочне рішення. Це образна основа, яку режисеру належить конкретизувати.\n\n2. Чим загальносценічний образ відрізняється від теми та ідеї?\n\nЦі поняття тісно пов’язані, але виконують різні функції.\n\nТема визначає, про що постановка.\n\nІдея визначає, яку головну думку режисер прагне донести до глядача.\n\nЗагальносценічний образ визначає, у якій художній формі ця думка постає перед глядачем.\n\nРозглянемо приклад.\n\nТема: зв’язок поколінь в українській музиці.\n\nІдея: кожне нове покоління музикантів не лише продовжує традиції попередників, а й надає їм нового звучання.\n\nЗагальносценічний образ: «Музика як безперервна хвиля, що проходить крізь покоління».\n\nУ цьому випадку хвиля є художньою метафорою спадкоємності. Вона може знаходити відображення у формі сценічного простору, світловій пластиці, графічному оформленні, музичних переходах і взаємодії артистів різних поколінь.\n\nВажливо розуміти: загальносценічний образ не обов’язково має бути конкретним предметом  -  годинником, деревом, дзеркалом або дорогою.\n\nВін може бути побудований на явищі, стані, асоціації, метафорі або особливому художньому сприйнятті світу.\n\nНаприклад:\n\n* Місто, яке ніколи не засинає.\n* Світ, що поступово втрачає свої барви.\n* Пам’ять, яка існує поза часом.\n* Людина серед нескінченного інформаційного потоку.\n* Музика як простір зустрічі різних поколінь.\n\nГоловне, щоб обраний образ був пов’язаний з ідеєю постановки, а не існував лише заради зовнішньої ефектності.\n\n3. Із чого формується загальносценічний образ?\n\nЗагальносценічний образ виникає внаслідок взаємодії різних художніх складових постановки.\n\nДля режисури естради та шоу особливо важливими є візуальна, звукова (тональна), просторово-пластична, атмосферна й темпоритмічна складові.\n\nЦе не п’ять окремих образів, які обов’язково потрібно вигадати. Це різні сторони одного цілісного сценічного образу.\n\n3.1. Візуальна складова: як виглядає художній світ постановки?\n\nВізуальна складова охоплює все, що глядач сприймає зором: сценографію, освітлення, колір, відеоконтент, костюми, предмети, композицію сценічного простору, розташування виконавців.\n\nОднак візуальний образ  -  це не просто сукупність красивих зображень.\n\nВізуальний образ виникає тоді, коли зорові елементи об’єднані спільною художньою ідеєю.\n\nНаприклад, режисер створює музичне шоу, загальносценічний образ якого  -  «Людина у світі цифрових ілюзій».\n\nВізуальне рішення може ґрунтуватися на поєднанні реальних виконавців із цифровими двійниками, багатошаровими проєкціями, відображеннями та простором, у якому складно відрізнити справжнє від віртуального.\n\nУсі ці компоненти допомагають сформувати єдине візуальне враження.\n\nВодночас використання великої кількості LED-екранів саме по собі не створює візуального образу. Екрани є лише технічним засобом, за допомогою якого цей образ може бути втілений.\n\nТак само синє освітлення, дим, дзеркальні поверхні або чорні костюми не є самостійним загальносценічним образом. Вони набувають художнього значення лише в контексті цілісного задуму.\n\n3.2. Звукова (тональна) складова: як звучить художній світ постановки?\n\nЗвукова складова визначає характер звукового середовища, у якому існує сценічна дія.\n\nВона може формуватися через музику, голоси, тембри, шумові ефекти, тишу, звукові контрасти, просторове розташування звуку та особливості звучання виконавців.\n\nУ режисурі концертів і музичних шоу звукова складова має особливе значення, адже музика часто є не просто супроводом, а основним носієм художнього змісту.\n\nТональний образ  -  це цілісне художнє враження, яке створюється через організацію звучання постановки.\n\nНаприклад, загальносценічний образ концерту  -  «Голос міста».\n\nЙого звуковий світ може поєднувати звуки міського середовища, голоси людей, ритми транспорту, фрагменти вуличної музики, електронне звучання та живе виконання.\n\nУ такому випадку звуки міста не просто використовуються як фон. Вони формують особливий звуковий світ, у якому розгортається концерт.\n\nІнший приклад  -  музична вистава, загальносценічний образ якої пов’язаний із самотністю.\n\nЇї тональне рішення може ґрунтуватися на камерному звучанні, окремих голосах, тривалих паузах, відчутті звукової порожнечі.\n\nВажливо, що тональний образ не обов’язково означає постійне використання певної музики або одного звукового ефекту. Йдеться про загальну художню природу звучання.\n\n3.3. Просторово-пластична складова: як існує художній світ у сценічному просторі?\n\nСценічний простір  -  це не лише фізичний майданчик, на якому відбувається постановка.\n\nДля режисера простір може ставати носієм художнього змісту.\n\nВін може сприйматися як відкритий або замкнений, безмежний або обмежений, реалістичний або умовний, статичний або мінливий.\n\nВажливе значення має також характер присутності й руху виконавців у цьому просторі.\n\nНаприклад, у шоу про самотність людини серед великого міста режисер може створити величезний сценічний простір, у центрі якого перебуває один виконавець.\n\nНавіть без додаткових пояснень таке співвідношення масштабу людини й простору може викликати відчуття ізольованості.\n\nВ іншому проєкті, присвяченому єдності, художній образ може формуватися через спільну присутність великої кількості виконавців, їхнє пластичне поєднання та відчуття єдиного сценічного організму.\n\nОтже, просторово-пластична складова відповідає не просто на питання, де стоять або рухаються артисти, а який художній зміст створює їхнє існування у просторі.\n\nКонкретні мізансцени та способи організації руху розробляються на наступних етапах постановочної роботи.\n\n3.4. Атмосфера: що відчуває глядач у художньому світі постановки?\n\nАтмосфера визначає емоційне забарвлення сценічного світу.\n\nВона може бути святковою, тривожною, урочистою, інтимною, напруженою, загадковою, ностальгійною тощо.\n\nОднак атмосфера не виникає лише завдяки музиці або освітленню.\n\nВона формується через взаємодію всіх компонентів постановки.\n\nНаприклад, урочиста атмосфера церемонії може створюватися завдяки масштабному сценічному простору, характеру музики, світловому рішенню, поведінці ведучих, темпу появи лауреатів і загальному характеру події.\n\nВодночас один і той самий загальносценічний образ може містити різні атмосферні стани.\n\nНаприклад, концерт, побудований на образі пам’яті, може поєднувати світлу ностальгію, радість, сум, вдячність і відчуття урочистості.\n\nТому атмосфера не повинна обмежуватися одним прикметником. Важливо зрозуміти загальну емоційну природу постановки.\n\n3.5. Темпоритмічна складова: як глядач відчуває сценічний час?\n\nТемпоритм характеризує швидкість, інтенсивність, тривалість, чергування та внутрішню пульсацію сценічних процесів.\n\nДля режисури естради й шоу це особливо важливо, оскільки сприйняття постановки залежить не лише від змісту номерів, а й від їхньої тривалості, чергування, характеру переходів, пауз, контрастів та емоційних підйомів.\n\nТемпоритмічна складова може бути частиною загального образного бачення постановки.\n\nНаприклад, образ «Місто, яке ніколи не засинає» може передбачати відчуття безперервного руху, змінних ритмів, швидкого чергування вражень і несподіваних зупинок.\n\nНатомість образ «Час, що завмер» може передбачати уповільнені рухи, тривалі паузи, статичні композиції та відчуття розтягнутого сценічного часу.\n\nПроте на цьому етапі режисер ще не зобов’язаний розписувати точну темпоритмічну партитуру кожного епізоду.\n\nЙого завдання  -  визначити загальний характер сценічного часу, який відповідає художньому образу постановки.\n\n4. Як усі складові об’єднуються в один загальносценічний образ?\n\nНайважливіше  -  зрозуміти, що всі перелічені складові не існують незалежно одна від одної.\n\nРежисер не повинен спочатку вигадати окремий візуальний образ, потім зовсім інший звуковий образ, а потім намагатися механічно їх поєднати.\n\nУсі складові мають розкривати одне художнє бачення постановки.\n\nНаприклад, режисер створює концерт під умовною назвою «Пульс покоління».\n\nЙого загальносценічний образ  -  «Пульс як символ живої енергії покоління».\n\nЯк цей образ може проявлятися в різних складових?\n\nВізуально: пульсуючі світлові лінії, графічні імпульси, контрастні зміни освітлення.\n\nЗвуково: ритмічні пульсації, ударні інструменти, електронні імпульси, живі голоси.\n\nПросторово-пластично: відчуття колективної енергії, взаємозв’язку виконавців, спільного ритмічного існування.\n\nАтмосферно: молодість, напруга, енергія, прагнення до самовираження.\n\nТемпоритмічно: відчуття пульсації, чергування накопичення енергії та її вивільнення.\n\nУсі ці елементи формують один художній світ.\n\nВодночас режисер ще не визначив, як саме цей пульс організовуватиме послідовність номерів, яким буде головний постановочний прийом і як розвиватиметься сценарно-режисерський хід.\n\nЦе наступні питання режисерського задуму.\n\n5. Чому загальносценічний образ  -  це ще не режисерський прийом?\n\nЦе принципова відмінність.\n\nЗагальносценічний образ визначає художню природу постановки, а режисерський прийом  -  конкретний спосіб її сценічного втілення.\n\nНаприклад, загальносценічний образ  -  «Світ відображень».\n\nРежисер уявляє простір, у якому реальність постійно співіснує зі своїми відображеннями.\n\nУ візуальному рішенні можуть використовуватися дзеркальні поверхні, симетрія, відеозображення, подвоєння силуетів.\n\nУ звуковому  -  відлуння, повторення голосів, музичні відображення окремих фраз.\n\nВ атмосфері  -  відчуття невизначеності, загадковості, пошуку справжнього.\n\nЦе загальносценічний образ.\n\nА тепер режисер знаходить конкретне постановочне рішення:\n\nВиконавець починає взаємодіяти зі своїм відеовідображенням, яке поступово перестає повторювати його рухи й починає існувати самостійно.\n\nОсь це вже режисерський прийом.\n\nВін не просто описує художній світ, а визначає конкретний спосіб організації сценічної дії.\n\nІнакше кажучи:\n\nЗагальносценічний образ  -  яким є художній світ постановки.\n\nРежисерський прийом  -  яким сценічним способом режисер втілює певну частину цього світу.\n\nОбраз може існувати в режисерській уяві ще до того, як знайдено конкретні постановочні прийоми.\n\nА один загальносценічний образ може бути реалізований за допомогою багатьох різних прийомів.\n\n6. Чи кожна постановка обов’язково повинна мати символ або метафору?\n\nНі.\n\nЦе особливо важливо для режисури концертів, телевізійних шоу, церемоній нагородження та інших видовищних форм.\n\nНе кожен проєкт потребує буквального символу на зразок дерева, дороги, годинника, дзеркала або птаха.\n\nЗагальносценічний образ може формуватися через:\n\n* Особливу художню атмосферу.\n* Єдиний візуально-звуковий світ.\n* Стилістичну цілісність.\n* Образне трактування простору.\n* Художнє осмислення певного явища.\n* Спільний принцип сприйняття різних номерів.\n\nНаприклад, для сучасної музичної премії загальносценічний образ може ґрунтуватися на уявленні про музику як простір творчої свободи.\n\nДля великого гала-концерту  -  на відчутті зустрічі різних музичних світів.\n\nДля шоу-вистави  -  на створенні фантастичного простору, де звичні закони реальності не діють.\n\nГоловне  -  не наявність красивої метафори, а художня цілісність постановки.\n\nВодночас не варто плутати загальносценічний образ зі стилістикою.\n\nНаприклад, формулювання «сучасний концерт у футуристичному стилі» описує передусім естетичний напрям.\n\nЩоб воно стало повноцінним загальносценічним образом, потрібно зрозуміти, який саме художній світ створюється, що він означає та як пов’язаний з ідеєю проєкту.\n\n7. Як режисеру знайти загальносценічний образ?\n\nПошук загальносценічного образу починається не з вибору декорацій, кольорів або відеоефектів.\n\nНасамперед режисер має усвідомити тему, ідею та художню природу майбутньої постановки.\n\nДля цього варто послідовно відповісти на кілька питань.\n\n1. Яке головне враження має залишитися у глядача після постановки?\n\nНе лише що він повинен зрозуміти, а й що відчути та запам’ятати.\n\n2. Які образи, асоціації або метафори виникають у мене, коли я думаю про тему та ідею проєкту?\n\nВарто шукати не найефектніший символ, а той, який найточніше передає сутність задуму.\n\n3. Яким я уявляю художній світ постановки?\n\nЧи є він реалістичним або умовним, масштабним або камерним, відкритим або замкненим, світлим або тривожним?\n\n4. Як цей світ може проявитися в зоровому та звуковому рішенні?\n\nЯкі особливості простору, кольору, світла, музики, звуку й пластики допоможуть його сформувати?\n\n5. Чи пов’язані всі ці складові між собою?\n\nЧи створюють вони спільне художнє враження, чи існують лише як набір окремих ефектних рішень?\n\n6. Чи допомагає обраний образ розкрити ідею постановки?\n\nЦе найважливіша перевірка.\n\nЯкщо образ не має змістового зв’язку з ідеєю, він ризикує залишитися лише зовнішнім оформленням.\n\n8. Типові помилки під час визначення загальносценічного образу\n\nПомилка 1. Підміна образу технічними засобами.\n\n«Загальносценічний образ  -  велика LED-сцена з лазерами та димом».\n\nЦе опис технічного оснащення, а не художнього образу.\n\nПомилка 2. Підміна образу стилістикою.\n\n«Загальносценічний образ  -  мінімалізм, чорний колір, сучасна графіка».\n\nЦе характеристика оформлення. Потрібно пояснити, який художній зміст стоїть за таким рішенням.\n\nПомилка 3. Підміна образу атмосферою.\n\n«Загальносценічний образ  -  радість, свято, позитивні емоції».\n\nЦе бажаний емоційний стан, але ще не цілісний художній образ.\n\nПомилка 4. Підміна образу темою.\n\n«Загальносценічний образ  -  любов до України».\n\nЦе радше тематичне або ідейне формулювання. Необхідно знайти його художнє втілення.\n\nПомилка 5. Штучне вигадування символу.\n\n«Образ концерту  -  метелик», хоча ні тема, ні ідея, ні музичний матеріал не пояснюють такого вибору.\n\nСимвол не повинен з’являтися лише тому, що режисеру потрібно заповнити відповідний пункт.\n\nПомилка 6. Передчасний перехід до режисерського прийому.\n\n«Загальносценічний образ  -  артисти виходять через екран, який відкривається».\n\nЦе вже конкретне постановочне рішення. Спочатку потрібно визначити, який художній світ воно має втілювати.\n\n9. Що студент повинен представити в цьому пункті?\n\nУ розділі «Загальносценічний образ» необхідно описати цілісне художнє бачення майбутньої постановки.\n\nУ відповіді слід:\n\n1. Сформулювати загальносценічний образ  -  назвати або коротко охарактеризувати центральне художнє бачення постановки.\n2. Розкрити його зміст  -  пояснити, які асоціації, значення та емоції він має викликати.\n3. Обґрунтувати зв’язок із темою та ідеєю  -  чому саме такий образ допомагає розкрити задум.\n4. Описати основні складові образу  -  яким у загальних рисах є його візуальний, звуковий, просторово-пластичний, атмосферний і темпоритмічний характер.\n5. Пояснити художню цілісність  -  як ці складові поєднуються в єдиний сценічний світ.\n\nНа цьому етапі не потрібно детально розробляти режисерські прийоми, сценарно-режисерський хід, конкретні мізансцени, світлові команди або технічну партитуру.\n\nЦі рішення будуть розкриватися в наступних частинах режисерського задуму.\n\nГоловне, що потрібно запам’ятати\n\nЗагальносценічний образ  -  це не окремий предмет на сцені, не декорація, не візуальний ефект і не режисерський прийом.\n\nЦе цілісне художнє бачення постановки, яке виникає через взаємодію її змісту, сценічного простору, візуального та звукового світу, пластики, атмосфери й темпоритму.\n\nСпочатку режисер визначає, який художній світ він прагне створити. А вже потім шукає режисерські прийоми, за допомогою яких цей світ набуде конкретного сценічного втілення.","materialLinks":true,"imageReferences":true},{"id":"visualImage","type":"textarea","title":"3.1.2. Візуальна складова загальносценічного образу","wide":true,"rows":7,"help":"Опишіть загальну зорову концепцію, не дублюючи технічну сценографію.","placeholder":"Зоровий образ…","theory":"ВІЗУАЛЬНА СКЛАДОВА ЗАГАЛЬНОСЦЕНІЧНОГО ОБРАЗУ\n\n1. Що таке візуальна складова загальносценічного образу?\n\nВізуальна складова  -  це цілісне художнє уявлення режисера про те, як виглядає сценічний світ постановки та як через зорові образи розкривається її головна ідея.\n\nГлядач сприймає сценічний твір не лише через музику, слово чи дію, а й через усе, що бачить: простір, світло, колір, сценографію, костюми, відеозображення, рух виконавців та їхнє розташування на сцені.\n\nПроте візуальна складова загальносценічного образу  -  це не перелік цих елементів і не опис майбутнього технічного оформлення.\n\nЇї завдання  -  визначити спільну художню логіку зорового світу постановки.\n\nНаприклад, режисер створює концерт, присвячений творчому шляху артиста.\n\nЗагальносценічний образ  -  «Жива пам'ять».\n\nВізуальна складова може ґрунтуватися на співіснуванні минулого й сучасності: архівні зображення, фотографії, сучасні виконавці та сценічний простір сприймаються як частини одного художнього світу.\n\nУ такому випадку режисер ще не визначає, на якому екрані з'явиться фотографія або яким саме світловим приладом буде освітлений артист.\n\nВін визначає загальний характер візуального сприйняття постановки.\n\n2. Із чого формується візуальна складова?\n\nВізуальна складова може формуватися через кілька взаємопов'язаних характеристик.\n\nПростір і масштаб. Яким глядач сприймає сценічний світ: відкритим, замкненим, камерним, монументальним, безмежним, багаторівневим?\n\nКолір і світло. Які колірні співвідношення, контрасти, освітленість і характер світлового середовища визначають художню природу постановки?\n\nФорма та фактура. Які геометричні форми, поверхні, матеріали й зорові асоціації характерні для цього світу?\n\nЗображення та мультимедіа. Яку роль у формуванні образу можуть відігравати фотографії, відео, графіка, проєкції, цифрові зображення?\n\nЛюдина в сценічному просторі. Як присутність виконавців, їхні силуети, костюми, пластика та взаємне розташування впливають на загальне зорове враження?\n\nУсі ці складові не обов'язково мають бути однаково важливими.\n\nНаприклад, в одному проєкті основу візуального образу визначає світло, в іншому  -  сценічна архітектура, у третьому  -  людське тіло та пластика.\n\nГоловне, щоб вони підпорядковувалися спільному художньому задуму.\n\n3. Як візуальна складова пов'язана з ідеєю постановки?\n\nВізуальна складова не повинна існувати лише заради красивого оформлення.\n\nЇї завдання  -  допомагати глядачеві сприймати зміст постановки через зорові асоціації.\n\nНаприклад:\n\nТема: людина в сучасному інформаційному суспільстві.\n\nІдея: серед безперервного потоку інформації людина ризикує втратити власну індивідуальність.\n\nЗагальносценічний образ: «Людина всередині інформаційного потоку».\n\nВізуальна складова: багатошаровий цифровий простір, велика кількість одночасних зображень, фрагментовані людські силуети, контраст між масштабом цифрового середовища та окремою людиною.\n\nУ цьому прикладі візуальне рішення не просто демонструє сучасні технології.\n\nВоно допомагає передати відчуття людини, яка перебуває під постійним інформаційним тиском.\n\n4. Чим візуальна складова відрізняється від сценографічного рішення?\n\nЦе важливе розмежування.\n\nВізуальна складова визначає художній характер зорового світу постановки.\n\nСценографічне рішення визначає конкретну організацію та матеріальне втілення цього світу на сценічному майданчику.\n\nНаприклад, режисер уявляє сценічний світ як безмежний простір, у якому людина здається маленькою та самотньою.\n\nЦе характеристика візуальної складової.\n\nА конкретне рішення  -  чорний кабінет, система дзеркальних поверхонь, проєкційні площини, розташування подіумів та освітлювального обладнання  -  належить уже до сценографічної розробки.\n\nНа етапі визначення візуальної складової студент повинен описати художню концепцію, а не складати технічне завдання для художника-постановника.\n\n5. Як визначити візуальну складову власного проєкту?\n\nСпробуйте відповісти на такі питання:\n\n1. Яким я уявляю сценічний світ своєї постановки? Які перші зорові асоціації виникають, коли я думаю про загальносценічний образ?\n2. Який характер має цей світ? Він реалістичний чи умовний, відкритий чи замкнений, масштабний чи камерний, цілісний чи фрагментований?\n3. Які візуальні характеристики є для нього визначальними? Колір, світло, форма, фактура, простір, зображення, пластика?\n4. Яку роль у цьому світі відіграє людина? Вона є його центром, частиною загальної композиції чи протиставляється навколишньому простору?\n5. Як візуальне рішення допомагає розкрити ідею постановки? Що саме глядач повинен зрозуміти або відчути через зорові образи?\n6. Чи можна впізнати художній світ мого проєкту за його візуальними характеристиками? Чи це лише універсальне оформлення, яке можна використати в будь-якому концерті?\n\n6. Типові помилки\n\nПомилка 1. Перелік технічного обладнання замість художнього опису.\n\n«На сцені будуть LED-екрани, рухомі голови, лазери та дим».\n\nЦе технічні засоби, а не візуальна концепція.\n\nПомилка 2. Загальні характеристики без конкретного змісту.\n\n«Сцена буде сучасною, красивою, яскравою та ефектною».\n\nТаке формулювання не пояснює, чим саме візуальний світ цього проєкту відрізняється від інших.\n\nПомилка 3. Опис окремих номерів замість загального образу.\n\n«У першому номері червоне світло, у другому синє, у третьому відео з природою».\n\nЦе вже фрагменти постановочного плану. Необхідно визначити, що об'єднує їх у цілісну візуальну систему.\n\nПомилка 4. Відсутність зв'язку з ідеєю.\n\nВізуальне рішення може бути ефектним, але не мати жодного стосунку до змісту постановки.\n\n7. Що потрібно написати у своїй роботі?\n\nУ цьому пункті необхідно описати загальну візуальну концепцію постановки.\n\nПоясніть, яким ви бачите сценічний світ, які зорові характеристики його визначають, як вони пов'язані між собою та яким чином допомагають розкрити загальносценічний образ.\n\nНе потрібно детально описувати конструкції сцени, обладнання, світлові команди, відеоконтент кожного номера чи конкретні мізансцени.\n\nГоловне питання: яким глядач побачить художній світ моєї постановки і чому саме таким?","materialLinks":true,"imageReferences":true},{"id":"soundImage","type":"textarea","title":"3.1.3. Звукова (тональна) складова загальносценічного образу","wide":true,"rows":7,"help":"Опишіть художню природу звучання всього проєкту, а не лише перелік композицій.","placeholder":"Звуковий образ…","theory":"ЗВУКОВА (ТОНАЛЬНА) СКЛАДОВА ЗАГАЛЬНОСЦЕНІЧНОГО ОБРАЗУ\n\n1. Що таке звукова (тональна) складова?\n\nЗвукова (тональна) складова  -  це цілісне художнє уявлення режисера про звуковий світ постановки, через який розкриваються її зміст, атмосфера та загальносценічний образ.\n\nЗвук у сценічному творі не обмежується музичним супроводом.\n\nВін може включати людський голос, музику, шумові ефекти, природні звуки, електронні фактури, акустичне середовище, тишу, відлуння, темброві контрасти та інші звукові явища.\n\nУ режисурі естради й шоу звуковий світ має особливе значення, оскільки музика часто становить основний зміст концертної програми.\n\nОднак перелік музичних композицій ще не є тональним образом постановки.\n\nТональна складова визначає, як усі звукові елементи сприймаються в межах єдиного художнього задуму.\n\nНаприклад, загальносценічний образ концерту  -  «Голос покоління».\n\nЗвукова концепція може будуватися на взаємодії живих людських голосів, сучасного електронного звучання, традиційних інструментів і музичних інтонацій різних поколінь.\n\nУ такому випадку режисер формує не просто концертний плейлист, а художнє уявлення про звучання цілого покоління.\n\n2. Із чого формується тональна складова?\n\nДля її визначення важливо враховувати кілька характеристик.\n\nМузична природа постановки. Яке місце займає музика, які музичні стилі, інтонації та принципи звучання формують загальне враження?\n\nТембровий характер. Які звукові барви переважають: акустичні, електронні, оркестрові, камерні, вокальні, шумові?\n\nГолос. Яку художню роль відіграють спів, мовлення, шепіт, декламація, хор, записані голоси?\n\nЗвукове середовище. Чи існує в постановці особливий звуковий світ: місто, природа, механізми, цифрове середовище, простір пам'яті?\n\nТиша й пауза. Чи є відсутність звуку важливим художнім компонентом?\n\nЗвукові контрасти. Які співвідношення гучного й тихого, щільного й прозорого, живого й записаного звучання характеризують постановку?\n\nПросторовість звуку. Чи має значення, звідки саме глядач чує звук і як він сприймається в сценічному просторі?\n\nЦі характеристики допомагають сформувати цілісне уявлення про звукову природу проєкту.\n\nПри цьому не обов'язково використовувати всі можливі засоби. Іноді один голос, один інструмент або навіть тиша можуть стати визначальними складовими тонального образу.\n\n3. Як тональна складова допомагає розкрити ідею?\n\nЗвук може не лише супроводжувати сценічну дію, а й самостійно передавати художній зміст.\n\nНаприклад:\n\nТема: зв'язок людини з її культурним корінням.\n\nІдея: традиція залишається живою, коли знаходить нові форми існування в сучасності.\n\nЗагальносценічний образ: «Голос традиції в сучасному світі».\n\nТональна складова: поєднання автентичного вокалу, звучання традиційних інструментів, сучасної електронної музики та нових музичних інтерпретацій.\n\nУ такому проєкті взаємодія різних звукових світів допомагає розкрити ідею зв'язку минулого й сучасного.\n\nІнший приклад  -  музична шоу-вистава про внутрішній світ людини.\n\nЇї тональна складова може формуватися через зіставлення реального голосу персонажа та його внутрішнього голосу, акустичного й електронного звучання, музики та тиші.\n\nЦе дозволяє передавати внутрішні переживання не лише словами або дією, а й через саму природу звуку.\n\n4. Чим тональна складова відрізняється від музичного оформлення?\n\nТональна складова визначає художню концепцію звучання всієї постановки.\n\nМузичне та звукове оформлення  -  це конкретний добір, створення й організація звукового матеріалу для її реалізації.\n\nНаприклад, режисер визначає, що звуковий світ концерту повинен поєднувати відчуття живого людського голосу з масштабним симфонічним звучанням.\n\nЦе тональна концепція.\n\nА рішення використати певний оркестр, конкретні аранжування, музичні композиції, фонограми та звукові ефекти  -  це вже наступний етап роботи.\n\nОсобливо важливо розрізняти ці поняття в концертах, де музичний репертуар може бути визначений заздалегідь.\n\nНавіть якщо режисер не може змінювати композиції артистів, він може осмислити загальну звукову природу концерту, характер переходів, контрастів, пауз і взаємодії різних музичних номерів.\n\n5. Як визначити тональну складову власного проєкту?\n\nСпробуйте відповісти на такі питання:\n\n1. Як звучить художній світ моєї постановки? Які звукові асоціації виникають у мене, коли я уявляю загальносценічний образ?\n2. Яке місце займає музика? Вона є основним змістом проєкту, супроводжує дію чи допомагає створювати художнє середовище?\n3. Які звукові характеристики є визначальними? Голос, тембр, музична фактура, електроніка, акустичне звучання, шум, тиша?\n4. Чи існує звукова особливість, яка об'єднує різні частини постановки? Це може бути спільна музична природа, тембровий характер, звукове середовище або принцип контрасту.\n5. Як звуковий світ співвідноситься з візуальним? Вони підтримують одне одного, доповнюють чи свідомо створюють художній контраст?\n6. Як тональна складова допомагає розкрити головну ідею постановки? Який зміст глядач сприйматиме саме через звук?\n\n6. Типові помилки\n\nПомилка 1. Перелік музичних композицій.\n\n«У концерті звучатимуть пісні десяти українських артистів».\n\nЦе характеристика репертуару, а не тонального образу.\n\nПомилка 2. Опис технічного обладнання.\n\n«Використовуватиметься професійна акустична система, мікрофони та звукові процесори».\n\nЦе технічне забезпечення.\n\nПомилка 3. Надто загальне формулювання.\n\n«Музика буде сучасною, емоційною та якісною».\n\nТаке формулювання не пояснює художньої природи звукового світу.\n\nПомилка 4. Підміна тональної складової атмосферою.\n\n«Звук створюватиме святковий настрій».\n\nЦе лише бажаний емоційний ефект. Потрібно пояснити, які особливості звучання формують цей ефект.\n\nПомилка 5. Відсутність зв'язку із загальносценічним образом.\n\nЗвукова концепція не повинна існувати окремо від загального режисерського задуму.\n\n7. Що потрібно написати у своїй роботі?\n\nУ цьому пункті необхідно описати загальну звукову (тональну) концепцію постановки.\n\nПоясніть, як ви уявляєте звуковий світ проєкту, які музичні та звукові характеристики його визначають, як вони пов'язані із загальносценічним образом і яку роль відіграють у розкритті ідеї.\n\nНе потрібно складати перелік композицій, детально описувати музичне оформлення кожного номера або визначати конкретне звукове обладнання.\n\nГоловне питання: як звучить художній світ моєї постановки та чому саме таке звучання допомагає розкрити її ідею?","materialLinks":true,"imageReferences":true}]};
const DIRECTOR_SCENOGRAPHY_SECTION={"id":"director-scenography","title":"3.2. Сценографічне рішення","intro":"Сценографія визначає просторово-візуальне середовище постановки і те, як воно працює разом зі сценічною дією. Тут важливо не перелічити декорації, а сформулювати принцип організації простору, його образ, матеріальну основу, можливі трансформації та функцію в розвитку проєкту.","published":true,"chapter":3,"chapterTitle":"РЕЖИСЕРСЬКИЙ ЗАДУМ","blocks":[{"id":"scenographyDescription","type":"textarea","title":"3.2.1. Опис сценографічного рішення","wide":true,"rows":9,"help":"Опишіть просторовий принцип постановки, основні сценографічні елементи, матеріали й фактури, колір, масштаб, можливі трансформації та те, як простір взаємодіє зі сценічною дією.","placeholder":"Сценографічне рішення...","theory":"**Сценографічне рішення** - це не перелік декорацій і не опис красивої картинки. Воно визначає, яким є сценічний простір, за яким принципом він організований, як змінюється протягом постановки і яку художню функцію виконує.\n\nПочніть із загального просторового принципу: відкритий чи замкнений простір, фронтальний чи об'ємний, статичний чи трансформований, реалістичний, умовний, метафоричний або комбінований. Далі визначте основні матеріальні елементи: конструкції, подіуми, екрани, завіси, предмети, фактури, колір, масштаб та інші складові, якщо вони справді є частиною задуму.\n\nВажливо пояснити не тільки **що стоїть на сцені**, а **як сценографія працює в дії**: що відкриває або приховує, як формує зони, напрямки руху й центри уваги, як трансформується між частинами, як підтримує загальносценічний образ і режисерський прийом.\n\nНе підміняйте сценографічне рішення переліком техніки. LED-екран, світловий прилад або механічна конструкція стають частиною сценографії лише тоді, коли зрозуміла їхня художня функція в конкретному просторі.\n\n**Що саме написати.** Дайте цілісне уявлення про простір майбутньої постановки: його принцип, основні елементи, трансформації та зв'язок зі сценічною дією. Після прочитання інший член постановочної групи повинен уявити, як організований сценічний світ і чому він саме такий."},{"id":"scenographyReferences","type":"table","title":"3.2.2. Референси / ескізи сценографії","wide":true,"help":"Додайте власні ескізи або візуальні референси, які допомагають побачити сценографічний задум. Окремо дублювати опис рішення тут не потрібно.","columns":["№","Референси / ескізи"],"columnTypes":["sequence","images"],"tableSchemaVersion":2,"theory":"Цей пункт потрібен для **візуального уточнення вже сформульованого сценографічного рішення**. Додавайте власні ескізи, схеми простору, зображення конструкцій, фактур, матеріалів, кольорових або просторових рішень, які допомагають побачити задум.\n\nРеференс не замінює опис у попередньому пункті й не потребує окремого повторного пояснення в цій таблиці. Його завдання - зробити ваш задум візуально зрозумілішим."}]};
const DIRECTOR_TECHNIQUE_SECTION={"id":"director-technique","title":"3.3. Режисерський прийом","intro":"Режисерський прийом  -  постановочний спосіб організації матеріалу, який виявляє ідейну й образну сутність постановки та організує її в певному жанровому ключі, просторі й часі. Якщо прийомів декілька, один має бути основним, а інші  -  підпорядкованими.","published":true,"chapter":3,"chapterTitle":"РЕЖИСЕРСЬКИЙ ЗАДУМ","blocks":[{"id":"mainDirectorTechnique","type":"textarea","title":"3.3.1. Головний режисерський прийом","wide":true,"rows":7,"help":"Поясніть конкретну сценічну дію, спосіб її організації та художню мету. Прийом може бути локальним, а не обов’язково наскрізним.","placeholder":"Головний прийом полягає в тому, що…","theory":"РЕЖИСЕРСЬКИЙ ПРИЙОМ\n\n1. Що таке режисерський прийом?\n\nРежисерський прийом - це конкретний художній спосіб, за допомогою якого режисер організовує сценічну дію, розкриває зміст постановки та створює певне враження у глядача.\n\nПісля визначення теми, ідеї та загальносценічного образу потрібно відповісти на питання: як саме задум стане сценічною подією? Недостатньо написати «показати єдність поколінь». Треба придумати дію, через яку глядач відчує цю єдність.\n\nПриклад. Загальносценічний образ концерту пам'яті музиканта - «Жива пам'ять». На екрані з'являється архівний запис його виступу. Живий виконавець підхоплює музичну фразу, а потім голоси поєднуються. Це вже конкретний режисерський прийом, який робить зустріч минулого й сучасності відчутною.\n\nПрийом не обов'язково складний або технологічний. Він може ґрунтуватися на простій дії, паузі, зміні простору, взаємодії артистів або перетворенні звичайного предмета.\n\n2. Чим прийом відрізняється від загальносценічного образу?\n\nЗагальносценічний образ відповідає на питання «яким є художній світ?». Прийом відповідає на питання «що і як відбувається на сцені, щоб цей світ ожив?».\n\nОбраз «Світ відображень» може втілюватися різними прийомами: виконавець взаємодіє з відеодвійником, який перестає повторювати його рухи; артисти виконують однакову пластичну фразу із затримкою; глядач спершу бачить подію у відображенні, а вже потім безпосередньо. Один образ допускає багато прийомів.\n\n3. Як працює прийом?\n\nПеревіряйте кожне рішення трьома питаннями: ЩО відбувається? ЯК організована дія? ДЛЯ ЧОГО це потрібно?\n\nПриклад. У концерті про єдність спершу кожен виконавець перебуває в окремій світловій зоні й співає свою партію. Поступово голоси об'єднуються, освітлені зони зливаються, артисти формують спільну композицію. Дія: об'єднання виконавців. Спосіб: поступове поєднання голосів, світла та простору. Мета: дати глядачеві пережити єдність, а не лише почути про неї.\n\n4. Якими бувають режисерські прийоми?\n\nКонтраст. Після масштабного гучного номера сцена порожніє, а один артист починає співати без супроводу. Різниця масштабу й звучання надає його появі сили. Але не кожне чергування гучного й тихого є прийомом: потрібна художня мета.\n\nПовторення та варіація. Та сама мелодія спершу звучить дитячим голосом, потім у виконанні дорослого артиста, а у фіналі - хором. Повторення набуває нового змісту.\n\nТрансформація. Звичайні валізи спочатку є побутовими предметами, далі стають частиною декорації, а потім - символами людських історій і подорожей.\n\nОдночасна дія. Пісня, пластична історія на сцені та відеоряд розвиваються паралельно, доповнюючи або переосмислюючи одне одного. Важливо не перевантажити глядача.\n\nВзаємодія часових пластів. Архівний голос вступає в діалог із сучасним виконавцем, а історична фотографія переходить у живу сценічну композицію.\n\nЗміна точки сприйняття. Церемонія починається з погляду людей, які готують сцену, а не з урочистого виходу ведучих.\n\nХудожня організація простору. Виконавці переходять із центральної сцени до залу, змінюючи дистанцію між артистами та аудиторією; або великий простір звужується до однієї освітленої ділянки.\n\nВзаємодія з медіа. Артист передає уявний предмет персонажеві на екрані, а відеоперсонаж продовжує дію. Саме взаємодія, а не наявність екрана, становить прийом.\n\nЦе не закритий перелік. Можна поєднувати принципи та винаходити власні способи.\n\n5. Чому технічний ефект ще не є прийомом?\n\n«На сцені використовується дим» - технічний опис. «Простір поступово зникає в димі, і герой ніби переходить в іншу реальність» - можливий прийом, якщо такий перехід має значення для змісту. LED-екран, лазер, піротехніка або рухома платформа самі собою не доводять наявності режисерського рішення. Сильний прийом може взагалі не потребувати дорогого обладнання.\n\n6. Чи повинен прийом повторюватися весь концерт?\n\nНі. Він може працювати в одному номері, переході чи епізоді. Якщо певний принцип організовує взаємозв'язок і розвиток усієї програми, він може стати основою сценарно-режисерського ходу. Відмінність полягає у функції, а не тільки в масштабі.\n\n7. Як знайти власний прийом?\n\nЗапитайте себе: яку думку або відчуття я хочу передати? Яка сценічна дія зробить це видимим? Чи можна показати зміст без пояснювального тексту ведучого? Що саме повторюється, змінюється, протиставляється або взаємодіє? Які засоби необхідні? Як це пов'язано з образом та ідеєю? Що втратить постановка, якщо прибрати прийом?\n\n8. Типові помилки\n\n«Прийом - контраст» без пояснення, що саме протиставляється. «Прийом - LED-екран» замість опису сценічної дії. «Прийом - жива пам'ять» замість конкретного втілення образу. «Прийом - зворушлива атмосфера» замість способу її створення. Безперервне нагромадження ефектів. Копіювання чужого відеорішення без переосмислення для власного проєкту.\n\n9. Що студент повинен написати?\n\nНазвіть прийом; поясніть його принцип; опишіть, що відбувається на сцені; визначте учасників і засоби; обґрунтуйте художню мету та зв'язок із загальносценічним образом; зазначте, де прийом використовується. Не потрібно розписувати всі світлові команди чи технічну партитуру.\n\nЗразок. «Діалог сучасного виконавця з архівним образом артиста». Під час номера сучасний співак спершу слухає архівний запис, потім підхоплює фразу; наприкінці голоси поєднуються. Прийом втілює ідею продовження творчості в нових поколіннях та образ «Жива пам'ять».\n\nГоловне: ЩО відбувається? ЯК це організовано? ДЛЯ ЧОГО?\n\nРеференси та матеріали. За бажанням додайте фото, ескізи або графічні файли через завантаження зображень. Відео, аудіо, YouTube, Google Drive, сайти й музичні платформи додавайте тільки посиланнями. До кожного матеріалу поясніть, який принцип дії він демонструє. Референс не замінює вашого авторського рішення.","materialLinks":true},{"id":"secondaryDirectorTechniques","type":"textarea","title":"3.3.2. Додаткові режисерські прийоми","wide":true,"rows":6,"help":"За потреби зафіксуйте локальні або додаткові прийоми та поясніть, як вони підпорядковуються головному.","placeholder":"Додаткові прийоми…","theory":"Додаткові прийоми потрібні лише тоді, коли вони справді допомагають реалізувати задум. Для кожного поясніть, що відбувається, як це організовано і для чого. Не повторюйте головний прийом іншими словами."},{"id":"directorTechniqueReferences","type":"table","title":"3.3.3. Референси режисерського прийому","wide":true,"help":"Завантажуйте тільки зображення: фото, ескізи, схеми. Аудіо та відео додавайте посиланнями в основному полі прийому. До кожного референсу додайте короткий коментар.","columns":["№","Референси","Що саме демонструє цей референс"],"columnTypes":["sequence","images","text"],"tableSchemaVersion":1,"theory":"Референс тут потрібен не як «красива картинка», а як спосіб показати принцип дії прийому: трансформацію, взаємодію виконавця і простору, повтор, контраст, роботу з екраном, предметом, камерою або інший постановочний механізм."}]};
const DIRECTOR_MOVE_SECTION={"id":"director-move","title":"3.4. Сценарно-режисерський хід","intro":"Сценарно-режисерський хід допомагає інтегрувати різні матеріали й структурні частини в художнє ціле, проводити головну думку через увесь проєкт і задавати логіку його образного розгортання. Він не є обов’язковою декоративною «темою оформлення»: у деяких формах цілісність може бути забезпечена самою драматургією.","published":true,"chapter":3,"chapterTitle":"РЕЖИСЕРСЬКИЙ ЗАДУМ","blocks":[{"id":"scenarioDirectorMove","type":"textarea","title":"3.4.1. Сценарно-режисерський хід","wide":true,"rows":9,"help":"Поясніть, що саме об’єднує різні частини проєкту в одну образну логіку і як цей хід розвивається від початку до фіналу. Якщо окремий хід проєкту не потрібен  -  обґрунтуйте це.","placeholder":"Хід проєкту…","theory":"СЦЕНАРНО-РЕЖИСЕРСЬКИЙ ХІД\n\n1. Що таке сценарно-режисерський хід?\n\nСценарно-режисерський хід - це художній принцип, за допомогою якого режисер об'єднує частини постановки, організовує їхні взаємозв'язки та забезпечує розвиток твору від початку до фіналу.\n\nКонцерти, церемонії та шоу часто складаються з відносно самостійних номерів, відеосюжетів, виходів ведучих і нагороджень. Навіть професійно поставлені частини можуть залишитися набором виступів. Хід допомагає зробити їх цілісним сценічним твором.\n\nПриклад. Концерт про історію музики можна побудувати як послідовність пісень різних років. Але режисер знаходить інший принцип: короткий музичний мотив переходить між поколіннями, змінює стиль, тембр та виконавців і в фіналі звучить у спільному виконанні. Мотив стає не просто повтором, а способом зв'язку та розвитку програми.\n\n2. Відмінність від теми, ідеї та образу\n\nТема: зв'язок поколінь у музиці. Ідея: традиція живе в новому виконанні. Загальносценічний образ: «Музика як безперервна хвиля». Сценарно-режисерський хід: мотив передається від одних артистів іншим і поступово перетворюється. Тема відповідає «про що?», ідея - «яку думку?», образ - «який художній світ?», хід - «як цей світ розгортається впродовж постановки?».\n\n3. Чим хід відрізняється від прийому?\n\nУ режисерській практиці ці поняття можуть перетинатися. Хід іноді визначають як образний режисерський прийом, який об'єднує епізоди. Тому не потрібно вигадувати штучну абсолютну межу. Локальний дует із архівним відео - прийом одного номера. Якщо діалог минулого й сучасного стає способом зв'язку всіх частин концерту та розвивається до фіналу, він працює як сценарно-режисерський хід.\n\nЯкщо прийом і хід ґрунтуються на одному принципі, у полі прийому поясніть конкретну сценічну дію, а в полі ходу - зв'язок і розвиток усієї постановки.\n\n4. Що забезпечує хід?\n\nЄдність: чому різні номери належать до одного твору. Розвиток: що змінюється протягом постановки. Переходи: як пов'язані епізоди, а не лише як переставляють обладнання. Підпорядкування ідеї: чому кожна частина працює на головний зміст. Фінал: як початковий принцип отримує завершення або нове значення.\n\n5. На чому може ґрунтуватися хід?\n\nПодорож. Кожен район умовного нічного міста відкриває новий музичний світ, а маршрут має мету та розвиток.\n\nДіалог. Традиційна та сучасна музика спочатку звучать окремо, потім взаємодіють, а в фіналі народжується спільна композиція.\n\nПеретворення. Порожня сцена з кожним епізодом набуває нових елементів, і фінал відкриває цілісний художній простір.\n\nНаскрізний персонаж або образ. Умовний «Час» проводить глядача різними музичними епохами; важливі його дії та зміни, а не проста присутність.\n\nПовторюваний елемент із розвитком. Фраза «Я пам'ятаю» спершу звучить як особистий спогад, потім як голос покоління, а наприкінці - як колективне звернення.\n\nПоступове розкриття. Епізоди церемонії показують людину як митця, наставника та особистість; у фіналі ці грані поєднуються.\n\nЖоден із цих способів не є обов'язковим. Обирайте принцип, який випливає з матеріалу, а не лише красиво звучить.\n\n6. Чи потрібен концерту сюжет?\n\nНе обов'язково. Концерт може не мати персонажів, драматичної інтриги чи історії з послідовними подіями, але мати виразний образний розвиток: від особистого до колективного, від камерного до масштабного, від протиставлення до поєднання. Не варто примусово перетворювати кожен концерт на театральну п'єсу.\n\n7. Хід, композиція і сценарний план\n\nСценарний план визначає порядок: відкриття, номер, відеосюжет, нагородження, фінал. Композиція визначає співвідношення частин, підйоми та кульмінацію. Хід визначає художній принцип, що пов'язує їх і розвивається протягом усієї постановки. Ці речі взаємодіють, але не замінюють одна одну.\n\n8. Як знайти хід?\n\nЯкі епізоди вже є? Що їх змістовно об'єднує? Який художній принцип зробить зв'язок відчутним? Як він проявиться на початку? Що зміниться в середині? Як створюватиме переходи? До чого приведе в фіналі? Чи допомагає розкрити ідею? Найважливіше питання: що саме РОЗВИВАЄТЬСЯ протягом постановки?\n\n9. Типові помилки\n\n«Хід - історія української музики» - тема, а не спосіб розгортання. «Хід - хвиля» - лише образ без пояснення розвитку. Перелік номерів - сценарний план, а не хід. Однакова заставка перед кожним виступом не обов'язково створює художній зв'язок. Штучний персонаж або вигадана подорож можуть лише ускладнити просту концертну форму.\n\n10. Що студент повинен написати?\n\nСформулюйте хід, поясніть його зміст, що саме він об'єднує, як проявляється на початку, як змінюється в основних частинах, як організовує переходи та чим завершується. Покажіть зв'язок із загальносценічним образом та ідеєю.\n\nЗразок. «Передавання музичного мотиву між поколіннями». На початку мотив звучить у виконанні старших артистів, у наступних епізодах переходить до молодших, змінюється в аранжуванні й стилі. У фіналі всі виконавці об'єднуються. Хід поєднує номери та розкриває ідею спадкоємності.\n\nГоловне: ЩО об'єднує постановку? ЯК принцип розвивається? ДО ЧОГО приводить у фіналі?\n\nРеференси та матеріали. Додавайте графічні файли лише як зображення, а відео й аудіо - тільки через посилання. Пояснюйте, яку саме логіку об'єднання епізодів показує приклад. Не копіюйте чужий сценарно-режисерський хід механічно.","materialLinks":true,"imageReferences":true}]};
const DIRECTOR_MONTAGE_SECTION={"id":"director-montage","title":"2.4. Прийоми монтажу","intro":"Після визначення архітектоніки потрібно встановити, **за яким принципом окремі сценічні одиниці утворюють цілісний твір**. У цьому пункті студент формулює загальну монтажну логіку проєкту. Конкретний монтажний прийом для кожного стику уточнюється далі у сценарному плані.","published":true,"chapter":2,"chapterTitle":"СЦЕНАРНО-ДРАМАТУРГІЧНА ОСНОВА","blocks":[{"id":"montagePrinciples","type":"textarea","title":"2.4.1. Загальний принцип монтажу","wide":true,"rows":8,"help":"Визначте, які прийоми монтажу є основними у вашому проєкті та як вони працюють: послідовний, контрастний, паралельний, асоціативно-образний, лейтмотивний, ретроспективний або інші. Не просто перелічіть назви - поясніть логіку поєднання матеріалу.","placeholder":"Загальна монтажна логіка проєкту…","theory":"**Монтаж у сценічному творі** - це спосіб смислового, драматургічного й образного поєднання окремих сценічних одиниць. Значення виникає не лише всередині номера або епізоду, а й **у зіставленні одного фрагмента з іншим**.\n\nОсновні прийоми, які можуть використовуватися у сценічному проєкті:\n\n- **послідовний монтаж** - одна одиниця логічно або причинно продовжує попередню; матеріал розгортається як послідовний розвиток думки, події чи теми;\n- **контрастний монтаж** - сусідні фрагменти свідомо протиставляються за змістом, емоцією, темпом, стилем, масштабом або іншим принципом, і саме зіткнення створює новий смисл;\n- **паралельний монтаж** - дві або більше ліній, тем чи дій розвиваються почергово, дозволяючи глядачеві одночасно стежити за їхнім розвитком і зіставляти їх;\n- **асоціативно-образний монтаж** - фрагменти поєднуються через образ, метафору, слово, звук, пластику, предмет, колір, відео або іншу асоціативну ознаку, а не через прямий сюжетний зв’язок;\n- **лейтмотивний монтаж** - певний образ, музичний мотив, фраза, відеофрагмент, пластична дія чи інший елемент повторюється в різних частинах і щоразу набуває нового значення;\n- **ретроспективний монтаж** - теперішня сценічна дія співвідноситься з минулим через спогад, документ, архівний матеріал, повернення до раніше показаної події або іншої часової площини.\n\nУ реальному проєкті ці прийоми можуть поєднуватися. Не потрібно штучно будувати весь твір на одному прийомі.\n\n**Що заповнювати у цьому полі.** Назвіть **переважні монтажні принципи саме вашого проєкту** й коротко поясніть, де і навіщо вони працюють. Наприклад, якщо основою є контраст минулого й сучасного, поясніть, який матеріал зіставляється і який смисл народжується з цього зіставлення. Тут не потрібно розписувати кожен окремий стик - це буде зроблено у графі **«Монтажний прийом»** сценарного плану."}]};
const DIRECTOR_ATMOSPHERE_SECTION={"id":"director-atmosphere","title":"3.5. Атмосфера","intro":"Атмосфера  -  звуко-зорове та емоційне середовище сценічної дії. Вона розвивається разом із проєктом, тому її потрібно побачити не лише загалом, а й **по кожній структурній одиниці**.","published":true,"chapter":3,"chapterTitle":"РЕЖИСЕРСЬКИЙ ЗАДУМ","blocks":[{"id":"projectAtmosphere","type":"textarea","title":"3.5.1. Загальна характеристика атмосфери","wide":true,"rows":6,"help":"Коротко опишіть загальний атмосферний шлях постановки: від якого стану вона починається, як змінюється і до якого стану приходить у фіналі.","placeholder":"Загальна атмосфера проєкту розвивається від… до…","theory":"АТМОСФЕРА ПОСТАНОВКИ\n\n1. Що таке атмосфера?\n\nАтмосфера постановки - це цілісний емоційно-чуттєвий характер сценічного середовища, який виникає через взаємодію дії, виконавців, простору, музики, світла, звуку та пластики. Вона може відчуватися ще до появи артиста: як очікування, урочистість, тривога або таємничість. Атмосферу не можна просто «увімкнути» одним технічним засобом.\n\n2. Атмосфера та настрій\n\nНастрій може стосуватися персонажа, артиста, пісні або глядача. Атмосфера характеризує сценічну подію загалом. Сумна пісня в просторі, який поступово наповнюється світлом і голосами хору, може перейти від відчуття самотності до надії. Отже, атмосфера не обов'язково збігається з настроєм музики.\n\n3. Атмосфера та загальносценічний образ\n\nОбраз відповідає на питання «який художній світ створюємо?», атмосфера - «як він емоційно сприймається зараз?». В образі «Жива пам'ять» можуть послідовно виникати світла ностальгія, вдячність, відчуття втрати, радість зустрічі та надія. Це не різні образи, а різні стани одного світу.\n\n4. Із чого формується атмосфера?\n\nСценічна дія: що саме відбувається, чого очікують учасники. Виконавці: інтонації, поведінка, пластика, взаємодія. Музика й звук: тембри, тиша, шуми, голоси. Світло й колір: характер видимості, контрасти, зміна уваги; колір не має одного універсального емоційного значення. Простір: масштаб, відкритість, порожнеча, близькість. Темпоритм: швидкість, паузи, напруження. Аудиторія: оплески, спільний спів, тиша, реакції. Всі ці компоненти мають працювати разом.\n\n5. Чи повинна атмосфера бути однаковою?\n\nНі. Церемонія може починатися святковим очікуванням, переходити до зосередженості під час представлення номінантів, напруги перед оголошенням, радості після нього та щирості під час промови лауреата. Зміни можуть підтримувати єдність постановки. Але новий стан не потрібен у кожному номері: іноді важливе поступове поглиблення однієї атмосфери.\n\n6. Загальна атмосферна концепція\n\nУ текстовому полі опишіть емоційну природу проєкту в цілому, основні стани та їхній розвиток. Концерт пам'яті може поєднувати світлу ностальгію, вдячність і відчуття живої присутності. Молодіжне шоу - свободу, відкритість і творчу енергію. Церемонія - урочистість, повагу до досягнень, очікування та піднесення. Це не означає, що кожна частина матиме той самий настрій.\n\n7. Як заповнювати таблицю атмосфери?\n\nСтруктурні одиниці вже підтягуються з архітектоніки. У графі «Атмосфера» напишіть, який емоційно-чуттєвий стан виникає в конкретному епізоді та як він змінюється. У графі «Засоби створення атмосфери» поясніть, за допомогою яких сценічних дій, виконавських, музичних, звукових, світлових і просторових рішень цей стан формується.\n\nПриклади рядків:\nПролог. Атмосфера: «Таємничість, очікування, поступове наближення великої події». Засоби: «Напівтемрява, окремі звукові імпульси, поступове відкриття простору».\nВідкриття концерту. Атмосфера: «Святкове піднесення, енергія, спільність». Засоби: «Масштабна присутність артистів, активна музика, світлове розкриття сцени».\nЛіричний номер. Атмосфера: «Інтимність, щирість, зосередженість». Засоби: «Камерне світло, стриманий рух, увага до живого голосу».\nОголошення переможця. Атмосфера: «Напружене очікування з переходом до розрядки». Засоби: «Пауза, зосередженість ведучого, стриманий звук, акцент у момент оголошення».\nВшанування митця. Атмосфера: «Світла ностальгія, вдячність». Засоби: «Архівні матеріали, спогади, делікатне музичне оформлення».\nФінал. Атмосфера: «Єдність, радість, піднесення». Засоби: «Спільна присутність виконавців, розширення музичного звучання, відкрите світло».\n\n8. Чи може атмосфера змінитися всередині одного номера?\n\nТак. Наприклад: «Від внутрішньої тривоги та самотності до світлого відчуття надії». Засоби: «Поступове розширення простору, перехід від одного голосу до багатоголосся, зміна світла, приєднання виконавців». Така відповідь показує розвиток, а не просто називає емоцію.\n\n9. Питання для самоперевірки\n\nЯка атмосфера виникає на початку? Як змінюється? Чи відповідає змісту кожного епізоду? Чи є виправдані контрасти? Чи не повторюється один стан механічно? Де найсильніші зміни? Чи підтримують їх виконавці, звук, світло, простір і темпоритм? Яке відчуття залишається після фіналу?\n\n10. Типові помилки\n\nПисати лише «святкова» без конкретизації. Називати атмосферою «синє світло й дим», хоча це засоби. Автоматично прирівнювати настрій пісні до атмосфери. Повторювати «урочиста» в усіх рядках. Вигадувати випадкові емоції без зв'язку зі змістом. Не пояснювати, як стан створюється. Плутати атмосферу з реакцією глядача: оплески - можлива реакція, а не визначення атмосфери.\n\n11. Що студент повинен представити?\n\nУ загальному текстовому полі: емоційний характер художнього світу, визначальні атмосферні стани, їхній зв'язок із образом, розвиток від початку до фіналу та очікуване враження. У таблиці: атмосферу КОЖНОЇ структурної одиниці, можливу зміну стану всередині неї та конкретні засоби формування. Не копіюйте загальну концепцію в усі рядки.\n\nГоловне: атмосфера - не просто настрій пісні чи колір світла, а цілісне емоційно-чуттєве середовище сценічної події."},{"id":"projectAtmosphereTable","type":"atmosphere_linked","title":"3.5.2. Атмосфера за структурою проєкту","wide":true,"help":"Для кожної структурної одиниці вкажіть атмосферу та конкретні засоби її створення. Повний зразок заповнення є в теорії до таблиці.","theory":"АТМОСФЕРА ПОСТАНОВКИ\n\n1. Що таке атмосфера?\n\nАтмосфера постановки - це цілісний емоційно-чуттєвий характер сценічного середовища, який виникає через взаємодію дії, виконавців, простору, музики, світла, звуку та пластики. Вона може відчуватися ще до появи артиста: як очікування, урочистість, тривога або таємничість. Атмосферу не можна просто «увімкнути» одним технічним засобом.\n\n2. Атмосфера та настрій\n\nНастрій може стосуватися персонажа, артиста, пісні або глядача. Атмосфера характеризує сценічну подію загалом. Сумна пісня в просторі, який поступово наповнюється світлом і голосами хору, може перейти від відчуття самотності до надії. Отже, атмосфера не обов'язково збігається з настроєм музики.\n\n3. Атмосфера та загальносценічний образ\n\nОбраз відповідає на питання «який художній світ створюємо?», атмосфера - «як він емоційно сприймається зараз?». В образі «Жива пам'ять» можуть послідовно виникати світла ностальгія, вдячність, відчуття втрати, радість зустрічі та надія. Це не різні образи, а різні стани одного світу.\n\n4. Із чого формується атмосфера?\n\nСценічна дія: що саме відбувається, чого очікують учасники. Виконавці: інтонації, поведінка, пластика, взаємодія. Музика й звук: тембри, тиша, шуми, голоси. Світло й колір: характер видимості, контрасти, зміна уваги; колір не має одного універсального емоційного значення. Простір: масштаб, відкритість, порожнеча, близькість. Темпоритм: швидкість, паузи, напруження. Аудиторія: оплески, спільний спів, тиша, реакції. Всі ці компоненти мають працювати разом.\n\n5. Чи повинна атмосфера бути однаковою?\n\nНі. Церемонія може починатися святковим очікуванням, переходити до зосередженості під час представлення номінантів, напруги перед оголошенням, радості після нього та щирості під час промови лауреата. Зміни можуть підтримувати єдність постановки. Але новий стан не потрібен у кожному номері: іноді важливе поступове поглиблення однієї атмосфери.\n\n6. Загальна атмосферна концепція\n\nУ текстовому полі опишіть емоційну природу проєкту в цілому, основні стани та їхній розвиток. Концерт пам'яті може поєднувати світлу ностальгію, вдячність і відчуття живої присутності. Молодіжне шоу - свободу, відкритість і творчу енергію. Церемонія - урочистість, повагу до досягнень, очікування та піднесення. Це не означає, що кожна частина матиме той самий настрій.\n\n7. Як заповнювати таблицю атмосфери?\n\nСтруктурні одиниці вже підтягуються з архітектоніки. У графі «Атмосфера» напишіть, який емоційно-чуттєвий стан виникає в конкретному епізоді та як він змінюється. У графі «Засоби створення атмосфери» поясніть, за допомогою яких сценічних дій, виконавських, музичних, звукових, світлових і просторових рішень цей стан формується.\n\nПриклади рядків:\nПролог. Атмосфера: «Таємничість, очікування, поступове наближення великої події». Засоби: «Напівтемрява, окремі звукові імпульси, поступове відкриття простору».\nВідкриття концерту. Атмосфера: «Святкове піднесення, енергія, спільність». Засоби: «Масштабна присутність артистів, активна музика, світлове розкриття сцени».\nЛіричний номер. Атмосфера: «Інтимність, щирість, зосередженість». Засоби: «Камерне світло, стриманий рух, увага до живого голосу».\nОголошення переможця. Атмосфера: «Напружене очікування з переходом до розрядки». Засоби: «Пауза, зосередженість ведучого, стриманий звук, акцент у момент оголошення».\nВшанування митця. Атмосфера: «Світла ностальгія, вдячність». Засоби: «Архівні матеріали, спогади, делікатне музичне оформлення».\nФінал. Атмосфера: «Єдність, радість, піднесення». Засоби: «Спільна присутність виконавців, розширення музичного звучання, відкрите світло».\n\n8. Чи може атмосфера змінитися всередині одного номера?\n\nТак. Наприклад: «Від внутрішньої тривоги та самотності до світлого відчуття надії». Засоби: «Поступове розширення простору, перехід від одного голосу до багатоголосся, зміна світла, приєднання виконавців». Така відповідь показує розвиток, а не просто називає емоцію.\n\n9. Питання для самоперевірки\n\nЯка атмосфера виникає на початку? Як змінюється? Чи відповідає змісту кожного епізоду? Чи є виправдані контрасти? Чи не повторюється один стан механічно? Де найсильніші зміни? Чи підтримують їх виконавці, звук, світло, простір і темпоритм? Яке відчуття залишається після фіналу?\n\n10. Типові помилки\n\nПисати лише «святкова» без конкретизації. Називати атмосферою «синє світло й дим», хоча це засоби. Автоматично прирівнювати настрій пісні до атмосфери. Повторювати «урочиста» в усіх рядках. Вигадувати випадкові емоції без зв'язку зі змістом. Не пояснювати, як стан створюється. Плутати атмосферу з реакцією глядача: оплески - можлива реакція, а не визначення атмосфери.\n\n11. Що студент повинен представити?\n\nУ загальному текстовому полі: емоційний характер художнього світу, визначальні атмосферні стани, їхній зв'язок із образом, розвиток від початку до фіналу та очікуване враження. У таблиці: атмосферу КОЖНОЇ структурної одиниці, можливу зміну стану всередині неї та конкретні засоби формування. Не копіюйте загальну концепцію в усі рядки.\n\nГоловне: атмосфера - не просто настрій пісні чи колір світла, а цілісне емоційно-чуттєве середовище сценічної події."}]};
const DIRECTOR_TEMPO_RHYTHM_SECTION={"id":"director-tempo-rhythm","title":"3.6. Темпо-ритм","intro":"Темпо-ритм показує часову й енергетичну динаміку постановки. Спочатку сформулюйте загальний принцип розвитку всього проєкту, а потім конкретизуйте його для кожної структурної одиниці.","published":true,"chapter":3,"chapterTitle":"РЕЖИСЕРСЬКИЙ ЗАДУМ","blocks":[{"id":"projectTempoRhythm","type":"textarea","title":"3.6.1. Загальна темпо-ритмічна характеристика","wide":true,"rows":6,"help":"Опишіть загальний темпо-ритмічний шлях проєкту від початку до фіналу: підйоми, спади, паузи, переключення, кульмінації та загальний характер розвитку.","placeholder":"Темпо-ритм проєкту розвивається від... через... до...","theory":"**Темпо-ритм постановки** - це організація сценічного часу, швидкості змін і внутрішньої інтенсивності дії. Він визначає, як глядач переживає розвиток проєкту: де виникає імпульс, де потрібна пауза, де накопичується напруга, де відбувається розрядка і де досягається кульмінація.\n\nТемп і ритм пов'язані, але не тотожні. **Темп** характеризує швидкість перебігу дії. **Ритм** визначає співвідношення тривалостей, повторів, пауз, акцентів, напруження й розрядки. Тому повільний фрагмент може мати високу внутрішню інтенсивність, а швидкий номер може залишатися одноманітним.\n\nУ цьому пункті потрібно побачити проєкт **цілісно**. Опишіть його загальний темпо-ритмічний шлях: де дія набирає швидкість, де навмисно сповільнюється, як чергуються масштабні й камерні фрагменти, де потрібне переключення уваги, як будуються підйоми, паузи, спади та кульмінації.\n\nНе зводьте темпо-ритм до музичного BPM і не описуйте його лише словами «швидкий», «середній», «повільний». Важливо показати **динаміку розвитку всього твору** та її зв'язок із режисерським задумом."},{"id":"projectTempoRhythmTable","type":"tempo_linked","title":"3.6.2. Темпо-ритм за структурою проєкту","wide":true,"help":"Для кожної структурної одиниці опишіть її темпо-ритмічний характер і задайте умовну інтенсивність від 1 до 5. Назви та структура спільні з іншими пов'язаними таблицями й використовуються для побудови темпо-ритмічного профілю.","theory":"У цій таблиці загальна темпо-ритмічна концепція переводиться на рівень **конкретних структурних одиниць**. Для кожного фрагмента потрібно визначити не просто швидкість, а характер його сценічного часу: де дія ущільнюється, де розгортається повільніше, де виникає пауза, різкий імпульс, накопичення, спад або переключення.\n\nГрафа **«Темпо-ритмічна характеристика»** призначена для короткого опису того, як рухається саме цей фрагмент. Графа **«Інтенсивність 1-5»** - це умовна візуальна оцінка енергетичної напруги, а не оцінка якості і не BPM.\n\nТемпо-ритмічний профіль унизу автоматично показує зміну інтенсивності від однієї структурної одиниці до іншої. Він потрібен, щоб побачити всю постановку цілісно: чи є розвиток, контрасти, паузи, підйоми, спади й кульмінаційні точки.\n\nНазви точок на профілі беруться з назв структурних одиниць. Якщо назву або структуру змінено в будь-якій пов'язаній таблиці, після синхронізації вона має відобразитися й тут."}]};
const DIRECTOR_EXPLICATION_SECTION={"id":"director-explication","title":"3.7. Режисерська експлікація","intro":"**Режисерська експлікація** конкретизує постановочне втілення кожної структурної одиниці. Тут важливо описати не набір технічних засобів, а цілісну режисерську логіку: що відбувається на сцені, як організована дія і якими виразними засобами вона реалізується.","published":true,"chapter":3,"chapterTitle":"РЕЖИСЕРСЬКИЙ ЗАДУМ","blocks":[{"id":"directorExplication","type":"director_explication","title":"Режисерська експлікація","wide":true,"help":"Опишіть кожну структурну одиницю як цілісне постановочне рішення. Має бути зрозуміло, що відбувається на сцені, хто діє, як організовано простір і мізансцену, який режисерський прийом визначає фрагмент, як працюють сценографія, світло, звук, відео, пластика, темпо-ритм, атмосфера та переходи. Додавайте схеми мізансценування й візуальні референси там, де вони справді допомагають пояснити задум.","theory":"**Режисерська експлікація** відповідає на питання: **як конкретно ця структурна одиниця буде існувати на сцені?** Тут сценарний план перетворюється на постановочне рішення.\n\nНе сприймайте експлікацію як анкету, у якій потрібно механічно пройти однаковий перелік пунктів для кожного рядка. Різні структурні одиниці потребують різної деталізації. Музичний номер, вихід ведучого, документальний епізод, масова сцена або короткий перехід не можуть описуватися за однією формулою.\n\nУ графі **«Режисерське рішення / сценічне втілення»** дайте цілісний постановочний опис. Передусім має бути зрозуміло, **що відбувається на сцені, яка сценічна дія розгортається і як саме режисер її організовує**. Далі розкривайте ті складові, які реально визначають рішення конкретного фрагмента.\n\nЗалежно від характеру одиниці це можуть бути: учасники й центри уваги; логіка входів, виходів і взаємодії; простір, рівні, траєкторії та мізансцени; режисерський прийом і спосіб його реалізації; сценографічні трансформації та предметна дія; характер світла; музика, звук, тиша й шуми; відео або медіаконтент та його взаємодія з живою дією; пластика; темпо-ритмічний розвиток; атмосфера; головний смисловий або емоційний акцент; спосіб переходу з попередньої одиниці та підготовка наступної.\n\nНе потрібно обов'язково згадувати всі ці складові в кожному рядку. Важливо вибрати саме ті засоби, без яких неможливо зрозуміти ваше режисерське рішення.\n\n**Мізансценування.** У цю графу додавайте власні схеми, плани сцени, малюнки розташування та руху виконавців, ключові композиції й траєкторії. Схема повинна доповнювати текст, а не замінювати його.\n\n**Візуалізація / референси.** Тут можуть бути референси сценографії, відеодизайну, світла, костюмів, кольору, фактур, пластики, композиції простору, атмосфери та інших візуальних рішень. Референс не є готовим рішенням для копіювання. У тексті режисерського рішення поясніть, що саме з нього важливе для вашої постановки.\n\nЕксплікація має бути достатньо конкретною, щоб інший член постановочної групи міг уявити фрагмент і зрозуміти логіку його сценічного втілення. Водночас вона ще не є технічним монтажним листом, тому номери каналів, точні cue, службові команди та інші технічні деталі тут не потрібні, якщо вони не мають принципового значення для розуміння самого режисерського рішення."}]};
function inferTableColumnType(label,current=''){
 const raw=String(label||'').trim(),t=raw.toLowerCase();
 if(['text','sequence','duration','images'].includes(String(current||'')))return String(current);
 if(/^№\s*$/i.test(raw)||/^№\s*п\/?п\s*$/i.test(raw))return 'sequence';
 if(/хронометраж|триваліст/.test(t))return 'duration';
 if(/референс|зображенн|картин|фото/.test(t))return 'images';
 return 'text';
}
