 const cv=Number(base.contentVersion||0);
 const clone=v=>JSON.parse(JSON.stringify(v));
 const upsert=(tpl,afterId='')=>{const i=base.sections.findIndex(s=>String(s.id)===String(tpl.id));if(i>=0){const published=base.sections[i].published!==false;base.sections[i]={...clone(tpl),published};return}let at=afterId?base.sections.findIndex(s=>String(s.id)===String(afterId)):-1;base.sections.splice(at>=0?at+1:base.sections.length,0,clone(tpl));};
