 const orderMap=new Map(desiredOrder.map((id,i)=>[id,i]));base.sections.sort((a,b)=>(orderMap.get(String(a.id))??999)-(orderMap.get(String(b.id))??999));
 for(const sec of base.sections){if(Number(sec.chapter||1)===1&&(!String(sec.chapterTitle||'').trim()||/^РОЗДІЛ\s*1$/i.test(String(sec.chapterTitle||''))))sec.chapterTitle='РЕЖИСЕРСЬКИЙ АНАЛІЗ'}
 if(cv<20){upsert(DIRECTOR_SCENOGRAPHY_SECTION,'director-image');upsert(DIRECTOR_TEMPO_RHYTHM_SECTION,'director-atmosphere');upsert(DIRECTOR_EXPLICATION_SECTION,'director-tempo-rhythm');}
 base.contentVersion=Math.max(20,Number(base.contentVersion||0));
