const DEFAULT_SCHEMA={version:1,contentVersion:20,title:"Режисерська лабораторія",subtitle:"Індивідуальна траєкторія розробки режисерського проєкту",sections:[JUSTIFICATION_SECTION,PROJECT_PARAMETERS_SECTION,RESEARCH_SECTION,IDEOLOGICAL_ANALYSIS_SECTION,SCENARIO_PLOT_SECTION,SCENARIO_COMPOSITION_SECTION,SCENARIO_ARCHITECTURE_SECTION,DIRECTOR_MONTAGE_SECTION,SCENARIO_PLAN_SECTION,DIRECTOR_IMAGE_SECTION,DIRECTOR_SCENOGRAPHY_SECTION,DIRECTOR_TECHNIQUE_SECTION,DIRECTOR_MOVE_SECTION,DIRECTOR_ATMOSPHERE_SECTION,DIRECTOR_TEMPO_RHYTHM_SECTION,DIRECTOR_EXPLICATION_SECTION].map(v=>JSON.parse(JSON.stringify(v)))};
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
