    const lines=part.split('\n');
    const first=lines[0].trim();
    if(/^#{1,4}\s+/.test(first)){const depth=Math.min(4,(first.match(/^#+/)||['#'])[0].length);return `<h${depth}>${first.replace(/^#{1,4}\s+/,'')}</h${depth}>`+(lines.length>1?`<p>${lines.slice(1).join('<br>')}</p>`:'')}
