function materialCollectionHtml(section,block,a,state){const isResearch=section.id==='research-materials',disabled=(!isResearch&&state==='approved')?'disabled':'',items=Array.isArray(a.items)?a.items:[];const empty=block.collectionKind==='notes'?'Нотаток ще немає. Додайте першу думку, коли вона з’явиться.':'Матеріалів ще немає. Додайте першу знахідку.';return `<div class="material-collection material-collection-simple" data-material-collection="${esc(block.id)}">${items.map(x=>materialItemHtml(block,x,disabled)).join('')||`<div class="material-empty">${empty}</div>`}${disabled?'':`<button class="material-add" type="button" data-add-material="${esc(block.id)}">＋ ${block.collectionKind==='notes'?'Нова нотатка':'Додати матеріал'}</button>`}</div>`}
function collectMaterialItems(box,blockId){return[...box.querySelectorAll(`[data-material-collection="${CSS.escape(blockId)}"] [data-material-item]`)].map(card=>{const get=k=>card.querySelector(`[data-mi="${k}"]`);const oldId=card.dataset.materialItem;const section=schema.sections.find(s=>(s.blocks||[]).some(b=>b.id===blockId)),block=section?.blocks?.find(b=>b.id===blockId),prev=(answerFor(section,block)?.items||[]).find(x=>String(x.id)===String(oldId))||{};const links=[...card.querySelectorAll('[data-mi-link]')].map(x=>x.value.trim()).filter(Boolean);return{id:oldId,type:prev.type||'',status:prev.status||'found',important:!!prev.important,title:get('title')?.value.trim()||'',author:prev.author||'',source:prev.source||'',timecode:prev.timecode||'',description:get('description')?.value.trim()||prev.description||'',directorNote:get('directorNote')?.value.trim()||'',links,link:links[0]||'',files:Array.isArray(prev.files)?prev.files:[]}})}
function researchStats(){const s=schema.sections.find(x=>x.id==='research-materials');if(!s)return{documentary:0,artistic:0,notes:0,total:0};const out={documentary:0,artistic:0,notes:0,total:0};for(const b of(s.blocks||[])){const items=answerFor(s,b)?.items||[];out[b.collectionKind]=items.length;out.total+=items.length}return out}
function researchResultHtml(){const st=sectionState('research-materials'),stats=researchStats(),done=st.status==='collected';return `<div class="research-result"><div><span class="research-result-kicker">Результат етапу</span><h3>${done?'Первинний збір сформовано':'Матеріали накопичуються'}</h3><p>Це робочий розділ. Він не подається на перевірку, а продовжує поповнюватися в процесі роботи над проєктом.</p></div><div class="research-counts"><span><b>${stats.documentary}</b> документальних</span><span><b>${stats.artistic}</b> художніх</span><span><b>${stats.notes}</b> нотаток</span></div></div>`}
function reviewedBlock(block,html){const anchored=String(html||'').replace('<div class="work-block','<div data-lab-block="'+esc(block.id)+'" class="work-block');const extra=itemFeedbackHtml(block)+blockDraftActionHtml(block);const i=anchored.lastIndexOf('</div>');return i>=0?anchored.slice(0,i)+extra+anchored.slice(i):anchored+extra}
const TABLE_COLUMN_TYPE_LABELS={text:'Текст',sequence:'№ по порядку',duration:'Тривалість',images:'Референси / зображення'};
function tableColumnTypes(block){const cols=Array.isArray(block?.columns)?block.columns:[],types=Array.isArray(block?.columnTypes)?block.columnTypes:[];return cols.map((c,i)=>TABLE_COLUMN_TYPE_LABELS[types[i]]?types[i]:inferTableColumnType(c,types[i]))}
function durationSeconds(v){if(typeof v==='number'&&Number.isFinite(v))return Math.max(0,Math.round(v));const t=String(v??'').trim();if(!t)return 0;if(/^\d+(?:[.,]\d+)?$/.test(t))return Math.max(0,Math.round(Number(t.replace(',','.'))*60));const parts=t.split(':').map(x=>Number(x));if(parts.every(Number.isFinite)){if(parts.length===2)return Math.max(0,Math.round(parts[0]*60+parts[1]));if(parts.length===3)return Math.max(0,Math.round(parts[0]*3600+parts[1]*60+parts[2]))}const h=Number((t.match(/(\d+(?:[.,]\d+)?)\s*(?:год|h)/i)||[])[1]||0),m=Number((t.match(/(\d+(?:[.,]\d+)?)\s*(?:хв|min|m)/i)||[])[1]||0),sec=Number((t.match(/(\d+(?:[.,]\d+)?)\s*(?:сек|sec|s)/i)||[])[1]||0);return Math.max(0,Math.round(h*3600+m*60+sec))}
function formatDuration(v){const total=durationSeconds(v),h=Math.floor(total/3600),m=Math.floor((total%3600)/60),sec=total%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${m}:${String(sec).padStart(2,'0')}`}
function tableImages(v){if(Array.isArray(v))return v.filter(x=>x&&typeof x==='object'&&String(x.url||'').trim());if(v&&typeof v==='object'&&Array.isArray(v.images))return v.images.filter(x=>x&&String(x.url||'').trim());return[]}
function tableCellHasValue(v,type='text'){if(type==='sequence')return true;if(type==='images')return tableImages(v).length>0;if(type==='duration')return durationSeconds(v)>0;return String(v??'').trim().length>0}
function tableCellForMigration(v,type){if(type==='images')return tableImages(v);if(type==='duration')return durationSeconds(v);if(type==='sequence')return Number(v)||0;return v==null?'':String(v)}
function tableCellFromFirestore(v,type){if(v&&typeof v==='object'&&!Array.isArray(v)&&v.__remsTableCell===1){if(type==='images')return tableImages(v.images);if(type==='duration')return durationSeconds(v.seconds);if(type==='sequence')return Number(v.value)||0;return String(v.value??'')}return tableCellForMigration(v,type)}
function tableCellToFirestore(v,type){if(type==='images')return{__remsTableCell:1,kind:'images',images:tableImages(v)};if(type==='duration')return{__remsTableCell:1,kind:'duration',seconds:durationSeconds(v)};if(type==='sequence')return{__remsTableCell:1,kind:'sequence',value:Number(v)||0};return{__remsTableCell:1,kind:'text',value:String(v??'')}}
function normalizeTableRows(block,answer={}){const cols=Array.isArray(block?.columns)?block.columns:[],types=tableColumnTypes(block),rawRows=Array.isArray(answer?.rows)?answer.rows:[],rows=rawRows.map(r=>{if(Array.isArray(r))return[...r];if(r&&typeof r==='object'&&r.cells&&typeof r.cells==='object')return cols.map((_,i)=>tableCellFromFirestore(r.cells[`c${i}`],types[i]||'text'));return[]});if(!rows.length)return[];const stored=Array.isArray(answer?.columns)?answer.columns:[];
 if(block?.id==='scenarioPlan'&&stored.length===7&&stored.includes('Матеріал: текст, музика, відео, документ тощо'))return rows.map((r,ri)=>[ri+1,String(r[1]||''),'',[String(r[2]||'').trim(),String(r[4]||'').trim()?`Матеріал: ${String(r[4]||'').trim()}`:'',String(r[5]||'').trim()?`Сценічна / технічна дія: ${String(r[5]||'').trim()}`:''].filter(Boolean).join('\n'),String(r[3]||''),durationSeconds(r[6]),[]]);
 if(stored.length&&cols.length&&stored.join('\u0001')!==cols.join('\u0001'))return rows.map((row,ri)=>cols.map((col,ci)=>{if(types[ci]==='sequence')return ri+1;const exact=stored.indexOf(col);if(exact>=0)return tableCellForMigration(row[exact],types[ci]);const aliases=col==='Опис дії: що відбувається'?['Короткий зміст: що відбувається','Що відбувається']:col==='Хронометраж'?['Орієнтовний хронометраж','Хронометраж']:[];for(const a of aliases){const ai=stored.indexOf(a);if(ai>=0)return tableCellForMigration(row[ai],types[ci])}return types[ci]==='images'?[]:types[ci]==='duration'?0:''}));
 return rows.map((r,ri)=>cols.map((_,i)=>tableColumnTypes(block)[i]==='sequence'?ri+1:tableCellForMigration(r[i],types[i])))
}
function tableAnswerToFirestore(block,answer={}){if(block?.type!=='table')return answer;const types=tableColumnTypes(block),rows=normalizeTableRows(block,answer).map(row=>({cells:Object.fromEntries((block.columns||[]).map((_,i)=>[`c${i}`,tableCellToFirestore(row[i],types[i]||'text')]))}));return{...answer,rows,columns:[...(block.columns||[])],columnTypes:[...types],tableSchemaVersion:Number(block.tableSchemaVersion||1)}}
function answerToFirestore(block,answer){return block?.type==='table'?tableAnswerToFirestore(block,answer):answer}
function tableGalleryHtml(images,{disabled=false,blockId='',row=0,col=0}={}){const list=tableImages(images);return `<div class="table-image-cell" data-table-images data-images="${esc(JSON.stringify(list))}"><div class="table-image-grid">${list.map((img,ii)=>`<div class="table-image-thumb"><a href="${esc(img.url)}" target="_blank" rel="noopener"><img src="${esc(img.url)}" alt="${esc(img.name||'Референс')}"></a>${disabled?'':`<button type="button" data-table-image-remove="${esc(blockId)}" data-row="${row}" data-col="${col}" data-image-index="${ii}" aria-label="Видалити">×</button>`}</div>`).join('')}</div>${disabled?'':`<label class="table-image-add"><input type="file" accept="image/*" multiple data-table-image-upload="${esc(blockId)}" data-row="${row}" data-col="${col}"><span>＋ Додати референс</span></label>`}</div>`}
function tableCellHtml(block,value,ri,ci,disabled=false){const type=tableColumnTypes(block)[ci]||'text',dis=disabled?'disabled':'';if(type==='sequence')return `<div class="table-sequence">${ri+1}</div>`;if(type==='duration'){const total=durationSeconds(value),m=Math.floor(total/60),sec=total%60;return `<div class="table-duration-input"><label><input type="number" min="0" step="1" value="${m}" data-duration-min ${dis}><small>хв</small></label><span>:</span><label><input type="number" min="0" max="59" step="1" value="${sec}" data-duration-sec ${dis}><small>сек</small></label></div>`}if(type==='images')return tableGalleryHtml(value,{disabled,blockId:block.id,row:ri,col:ci});return `<textarea data-table-text ${dis}>${esc(value??'')}</textarea>`}
function collectTableCell(td,type){if(type==='sequence')return Number(td.closest('tr')?.rowIndex||1);if(type==='duration'){const m=Math.max(0,Number(td.querySelector('[data-duration-min]')?.value||0)),s=Math.max(0,Math.min(59,Number(td.querySelector('[data-duration-sec]')?.value||0)));return Math.round(m*60+s)}if(type==='images'){try{return JSON.parse(td.querySelector('[data-table-images]')?.dataset.images||'[]')}catch{return[]}}return td.querySelector('[data-table-text]')?.value.trim()||''}
function tableDurationTotal(block,rows){const types=tableColumnTypes(block),idx=types.findIndex(x=>x==='duration');return idx<0?0:rows.reduce((sum,r)=>sum+durationSeconds(r?.[idx]),0)}
function tableDurationFooter(block,rows){const total=tableDurationTotal(block,rows);return tableColumnTypes(block).includes('duration')?`<div class="table-duration-total" data-duration-total="${esc(block.id)}"><span>Загальний хронометраж</span><b>${formatDuration(total)}</b></div>`:''}
