const ARCH_PART_KIND_LABELS={intro:'Інтро',number:'Номер',episode:'Епізод',block:'Блок',final:'Фінал',other:'Інше'};
const STAGE_UNIT_TYPES=['Інтро','Епізод','Фінал','Номер','Вокальний номер','Хореографічний номер','Музичний номер','Сцена','Відеофрагмент','Текст ведучого','Монолог','Виступ офіційної особи','Інтерактив','Документальний матеріал','Перформативна дія','Музичний фрагмент','Інсталяція','Інше'];
function linkedId(prefix='item'){try{return crypto.randomUUID()}catch{return`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`}}
function cloneJson(v){try{return JSON.parse(JSON.stringify(v))}catch{return v}}
function legacyRowsFromAnswer(a){const cols=Array.isArray(a?.columns)?a.columns:[],types=Array.isArray(a?.columnTypes)?a.columnTypes:[],raw=Array.isArray(a?.rows)?a.rows:[];return raw.map(r=>{if(Array.isArray(r))return r;if(r&&typeof r==='object'&&r.cells&&typeof r.cells==='object')return cols.map((_,i)=>tableCellFromFirestore(r.cells[`c${i}`],types[i]||'text'));return[]})}
function joinDramaturgy(...vals){const out=[];for(const v of vals){const x=String(v||'').trim();if(x&&!out.includes(x))out.push(x)}return out.join('\n\n')}
function partsToStructureRows(parts=[]){const rows=[];for(const p of parts||[]){const pid=String(p.id||linkedId('row')),ptype=ARCH_PART_KIND_LABELS[p.kind]||String(p.kind||'Інше');rows.push({id:pid,type:ptype,title:String(p.title||''),dramaturgy:joinDramaturgy(p.summary,p.principle,p.function)});for(const u of(Array.isArray(p.units)?p.units:[]))rows.push({id:String(u.id||linkedId('row')),type:String(u.type||'Одиниця сценічної інформації'),title:String(u.title||''),dramaturgy:String(u.summary||'')})}return rows}
function legacyStructureAndScenario(){const archNow=work?.answers?.architectureStructure,planNow=work?.answers?.scenarioPlan||{};if(archNow&&Array.isArray(archNow.parts)){return{architecture:{rows:partsToStructureRows(archNow.parts)},scenario:planNow&&planNow.items?cloneJson(planNow):{items:{}}}}const archOld=work?.answers?.architectureEpisodes||{},planOld=work?.answers?.scenarioPlan||{},archRows=legacyRowsFromAnswer(archOld),planRows=legacyRowsFromAnswer(planOld),rows=[],scenarioItems={};if(archRows.length){archRows.forEach((r,i)=>rows.push({id:`legacy-row-${i}`,type:'Епізод',title:String(r[0]||`Епізод ${i+1}`).trim(),dramaturgy:joinDramaturgy(r[3],r[1])}))}else if(planRows.length){planRows.forEach((r,i)=>{const id=`legacy-row-${i}`;rows.push({id,type:String(r[1]||'Номер').trim()||'Номер',title:String(r[2]||`Одиниця ${i+1}`).trim(),dramaturgy:''});scenarioItems[id]={script:String(r[3]||'').trim(),event:String(r[3]||'').trim(),duration:durationSeconds(r[5]),legacyParticipants:String(r[4]||'').trim(),legacyReferences:tableImages(r[6])}})}if(planRows.length&&rows.length){planRows.forEach((r,i)=>{const row=rows[i];if(!row)return;scenarioItems[row.id]={...(scenarioItems[row.id]||{}),script:String(r[3]||scenarioItems[row.id]?.script||'').trim(),event:String(r[3]||scenarioItems[row.id]?.event||'').trim(),duration:durationSeconds(r[5]),legacyParticipants:String(r[4]||'').trim(),legacyReferences:tableImages(r[6])}})}return{architecture:{rows},scenario:{items:scenarioItems}}}
function architectureData(){const a=work?.answers?.architectureStructure;if(a&&Array.isArray(a.rows))return{rows:a.rows.map((r,i)=>({id:String(r?.id||linkedId('row')),type:String(r?.type||''),title:String(r?.title||''),dramaturgy:String(r?.dramaturgy??r?.summary??'')}))};if(a&&Array.isArray(a.parts))return{rows:partsToStructureRows(a.parts)};return legacyStructureAndScenario().architecture}
function scenarioData(){const a=work?.answers?.scenarioPlan;if(a&&a.items&&typeof a.items==='object'&&!Array.isArray(a.items))return cloneJson(a);return legacyStructureAndScenario().scenario}
function explicationData(){const a=work?.answers?.directorExplication;if(a&&a.items&&typeof a.items==='object'&&!Array.isArray(a.items))return cloneJson(a);const legacy=legacyStructureAndScenario().scenario,items={};for(const[id,x]of Object.entries(legacy.items||{})){if((x.legacyReferences||[]).length)items[id]={references:tableImages(x.legacyReferences)}}return{items}}
function atmosphereData(){const a=work?.answers?.projectAtmosphereTable;return a&&a.items&&typeof a.items==='object'&&!Array.isArray(a.items)?cloneJson(a):{items:{}}}
function tempoRhythmData(){const a=work?.answers?.projectTempoRhythmTable;return a&&a.items&&typeof a.items==='object'&&!Array.isArray(a.items)?cloneJson(a):{items:{}}}
function linkedStructuralRole(value){const t=String(value||'').trim().toLowerCase();if(!t)return'unit';if(/(^|\s)(інтро|епізод|фінал)(\s|$|\d)/i.test(t))return'heading';return'unit'}
function linkedHierarchy(rows=[]){let top=0,child=0,inHeading=false;return(rows||[]).map((r,index)=>{const role=linkedStructuralRole(r?.type),x={sourceId:String(r?.id||''),type:String(r?.type||''),title:String(r?.title||''),dramaturgy:String(r?.dramaturgy||''),index,role,isHeading:role==='heading',level:0,displayNo:''};if(role==='heading'){top++;child=0;inHeading=true;x.displayNo=String(top);x.level=0}else if(inHeading){child++;x.displayNo=`${top}.${child}`;x.level=1}else{top++;x.displayNo=String(top);x.level=0}return x}).filter(x=>x.sourceId)}
