function activityFieldChange(label,before,after){const a=String(before??'').trim(),b=String(after??'').trim();if(a===b)return'';if(!a&&b)return`${label}: додано ${activityQuote(b)}`;if(a&&!b)return`${label}: видалено ${activityQuote(a)}`;return`${label}: було ${activityQuote(a)}. Стало ${activityQuote(b)}`}
