async function exportAll(){const zip=new JSZip(),links=[],files=[];const wordBlob=await buildTextDocx();zip.file('01_Текстові_матеріали.docx',wordBlob);for(const section of publishedSections()){for(const block of(section.blocks||[])){const a=answerFor(section,block)||{};if(block.type==='table'){const cols=block.columns||[],types=tableColumnTypes(block),rows=normalizeTableRows(block,a),csvCell=(v,i)=>{const type=types[i]||'text';if(type==='sequence')return'';if(type==='duration')return formatDuration(v);if(type==='images')return tableImages(v).map(x=>x.url||x.name||'').filter(Boolean).join(' | ');return String(v??'')};const csv='\uFEFF'+[cols,...rows].map(r=>r.map((v,i)=>`"${csvCell(v,i).replace(/"/g,'""')}"`).join(';')).join('\r\n');zip.file(`02_Таблиці/${safeFileName(section.title)}_${safeFileName(block.title)}.csv`,csv)}else if(block.type==='file'){for(const f of(a.files||[]))files.push(`${section.title}  -  ${block.title}: ${f.name}  -  ${f.url}`)}else if(block.type==='link'){const v=String(a.value||'').trim();if(v)links.push(`${block.title}: ${v}`)}}}zip.file('03_Посилання.txt',links.join('\n'));zip.file('04_Прикріплені_файли.txt',files.join('\n'));const blob=await zip.generateAsync({type:'blob'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${safeFileName(work.name)}_режисерська_лабораторія.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function openTheoryModal(btn){const modal=appEl.querySelector('#theoryModal');if(!modal)return;appEl.querySelector('#theoryModalTitle').textContent=btn.dataset.theoryTitle||'Теоретичний матеріал';appEl.querySelector('#theoryModalCopy').innerHTML=rich(btn.dataset.theory||'');modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}function closeTheoryModal(){const modal=appEl.querySelector('#theoryModal');if(!modal)return;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}

