async function downloadProjectParametersWord(){try{const section=schema.sections.find(x=>x.id==='project-parameters'),answers=currentSectionAnswers('project-parameters');const blob=await buildStandaloneDocx('1.2. ВИХІДНІ ПАРАМЕТРИ ПРОЄКТУ',(paras)=>{for(const block of(section?.blocks||[])){if(['theory','logic_chain','material_collection'].includes(block.type))continue;const a=answers[block.id]||{};let value=block.type==='checklist'?(a.values||[]).join(', '):String(a.value||'').trim();paras.push(docxPara(block.title||'Пункт',{bold:true,firstLine:false,spaceBefore:160,spaceAfter:80}));if(value)standaloneText(paras,value);else paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}));}});triggerBlobDownload(blob,`${safeFileName(work.name)}_1.2_Вихідні_параметри.docx`)}catch(e){console.error(e);alert(e.message||'Не вдалося сформувати Word.')}}
