async function genericSectionToDocx(paras,ctx,section){for(const block of section.blocks||[]){if(['logic_chain','theory'].includes(block.type))continue;const a=answerFor(section,block)||{};paras.push(docxPara(block.title||'Пункт',{bold:true,firstLine:false,spaceBefore:150,spaceAfter:60}));if(block.type==='architecture_builder'){await architectureLinkedToDocx(paras,ctx);continue}if(block.type==='scenario_linked'){await scenarioLinkedToDocx(paras,ctx);continue}if(block.type==='director_explication'){await explicationLinkedToDocx(paras,ctx);continue}if(block.type==='atmosphere_linked'){await linkedMatrixToDocx(paras,ctx,'atmosphere');continue}if(block.type==='tempo_linked'){await linkedMatrixToDocx(paras,ctx,'tempo');continue}if(block.type==='table'){await standaloneTableToDocx(paras,ctx,block,a);continue}if(block.type==='checklist'){const v=(a.values||[]).join(', ');v?standaloneText(paras,v):paras.push(docxPara('Не заповнено',{firstLine:false}));continue}const value=String(a.value||'').trim();value?standaloneText(paras,value):paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}))}}

async function downloadScenarioSectionWord(sectionId){try{const section=(schema.sections||[]).find(x=>x.id===sectionId&&Number(x.chapter||1)===2);if(!section)throw new Error('Підрозділ Розділу 2 не знайдено.');const blob=await buildStandaloneDocx(section.title.toUpperCase(),async(paras,ctx)=>{await genericSectionToDocx(paras,ctx,section)});const num=(String(section.title||'').match(/^(2\.[0-9]+)/)||[])[1]||'2';const label=String(section.title||'').replace(/^2\.[0-9]+\.\s*/, '').replace(/[\/:*?"<>|]+/g,'_').replace(/\s+/g,'_');triggerBlobDownload(blob,`${safeFileName(work.name)}_${num}_${label}.docx`)}catch(e){console.error(e);alert(e.message||'Не вдалося сформувати Word.')}}
