async function loadSchema(){try{const s=await getDoc(schemaRef);schema=upgradeSchema(s.exists()?s.data():DEFAULT_SCHEMA)}catch(e){console.error(e);schema=upgradeSchema(DEFAULT_SCHEMA)}}
function normalizePhotoSrc(v){const x=String(v||'').trim();if(!x)return'';if(/^data:|^blob:|^https?:\/\//i.test(x))return x;if(x.startsWith('images/'))return `https://rems-44.github.io/REMS-44/${encodeURI(x)}`;return x}
async function loadPhoto(){photo='';try{
 const candidates=[];if(work?.mediaId)candidates.push(String(work.mediaId));
 for(const id of candidates){const s=await getDoc(doc(db,'rems_student_media',id));if(s.exists()){photo=normalizePhotoSrc(s.data()?.photoData||s.data()?.photoUrl);if(photo)return}}
 if(work?.studentId){const qs=await getDocs(query(collection(db,'rems_student_media'),where('studentId','==',String(work.studentId)),limit(1)));if(!qs.empty){photo=normalizePhotoSrc(qs.docs[0].data()?.photoData||qs.docs[0].data()?.photoUrl);if(photo)return}}
 if(work?.mediaId){const ps=await getDoc(doc(db,'rems_public_profiles',String(work.mediaId)));if(ps.exists()){photo=normalizePhotoSrc(ps.data()?.photo||ps.data()?.photoData);if(photo)return}}
 photo=normalizePhotoSrc(work?.photoUrl||'');
 }catch(e){console.error('Photo',e)}}
await loadSchema();
onSnapshot(schemaRef,snap=>{try{const drafts=work?captureDirtyAnswers():{};const next=upgradeSchema(snap.exists()?snap.data():DEFAULT_SCHEMA);const changed=JSON.stringify(next?.sections||[])!==JSON.stringify(schema?.sections||[]);schema=next;if(work&&changed){work=mergeDirtyAnswers(work,drafts);render()}}catch(e){console.error('Schema live update:',e)}},err=>console.error('Schema listener:',err));
onSnapshot(workRef,async snap=>{if(!snap.exists()){fail('Лабораторію ще не активовано','Попроси викладача активувати персональний доступ у REMS-Control.');return}const drafts=work?captureDirtyAnswers():{},incoming=snap.data()||{};savedAnswersBaseline=cloneJson(incoming.answers||{});work=mergeDirtyAnswers(incoming,drafts);render();if(!photo)loadPhoto().then(()=>{if(work&&photo)render()}).catch(console.error)},err=>{console.error(err);fail('Не вдалося відкрити лабораторію','Перевір посилання та інтернет-з’єднання.')});
onSnapshot(feedbackRef,snap=>{const drafts=work?captureDirtyAnswers():{};const nextFeedback=snap.exists()?snap.data()||{}:{};notifyLocalFeedback(nextFeedback);feedback=nextFeedback;if(work){work=mergeDirtyAnswers(work,drafts);render();setTimeout(()=>{const u=unreadItemFeedbackEntries();if(u.length&&!document.getElementById('studentLiveNotice'))showStudentNotice(u.length===1?`У вас нова відповідь до пункту «${u[0].block.title||'Пункт'}»`:`У вас ${u.length} непрочитаних відповідей викладача`,u.length===1?u[0].block.id:'')},250)}},err=>{console.error('Feedback:',err);feedback={};if(work)render()});

