// Enable background notifications only when the student explicitly clicks the button.
function addStudentPushButton(){
 const header=document.querySelector('.lab-topbar');if(!header||document.getElementById('labEnablePush'))return;
 const b=document.createElement('button');b.id='labEnablePush';b.type='button';b.textContent=(('Notification'in window)&&Notification.permission==='granted')?'🔔 Сповіщення увімкнено':'🔔 Увімкнути сповіщення';b.style.cssText='margin:8px;padding:9px 12px;border-radius:9px;border:1px solid #9ca3af;background:white;color:#111827;cursor:pointer';
 b.onclick=async()=>{b.disabled=true;try{await enableBrowserNotifications();b.textContent=(('Notification'in window)&&Notification.permission==='granted')?'🔔 Сповіщення увімкнено':'🔔 Увімкнути сповіщення'}finally{b.disabled=false}};
 header.appendChild(b);
}
addStudentPushButton();
